/** Trim-and-decode wrapper over the shared decoder (`lib/html/entities.ts`).
 *  Was a six-entity copy; an entity-encoded Swedish site imported its own text
 *  as "h&aring;llbarhet". */
function decodeEntities(s: string): string {
  return decodeHtmlEntities(s).trim();
}

function stripTags(s: string): string {
  return decodeEntities(s.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim());
}

function detectLocale(html: string): "sv" | "en" {
  const m = html.match(/<html[^>]+lang=["']([^"']+)["']/i);
  return m && /^en/i.test(m[1]) ? "en" : "sv";
}

function headings(html: string, tag: "h1" | "h2"): string[] {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, "gi");
  return [...html.matchAll(re)]
    .map((m) => stripTags(m[1]))
    .filter((t) => t.length > 1 && t.length < 120);
}

/** Substantial paragraphs, each with where it sat in the document. */
function paragraphsAt(html: string): Array<{ text: string; at: number }> {
  return [...html.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)]
    .map((m) => ({ text: stripTags(m[1]), at: m.index ?? 0 }))
    .filter((p) => p.text.length >= 40);
}

function paragraphs(html: string): string[] {
  return paragraphsAt(html).map((p) => p.text);
}

/** All small headings (h2-h4) with the raw HTML that follows each, so detectors
 *  can pair a heading with its nearby content. */
function headingBlocks(html: string): Array<{ heading: string; body: string }> {
  const out: Array<{ heading: string; body: string }> = [];
  const re = /<(h[234])[^>]*>([\s\S]*?)<\/\1>([\s\S]*?)(?=<h[1-4][\s>]|$)/gi;
  for (const m of html.matchAll(re)) {
    const heading = stripTags(m[2]);
    if (heading.length > 1 && heading.length < 120) out.push({ heading, body: m[3] || "" });
  }
  return out;
}

/** FAQ: <details><summary>Q</summary>A</details> pairs, or a "?"-terminated
 *  small heading immediately followed by a paragraph. Emitted only with >=2. */
function detectFaq(html: string): Array<{ question: string; answer: string }> {
  const items: Array<{ question: string; answer: string }> = [];
  for (const m of html.matchAll(/<details[^>]*>\s*<summary[^>]*>([\s\S]*?)<\/summary>([\s\S]*?)<\/details>/gi)) {
    const q = stripTags(m[1]);
    const a = stripTags(m[2]);
    if (q && a && q.length < 200) items.push({ question: q, answer: a.slice(0, 600) });
  }
  if (items.length < 2) {
    for (const b of headingBlocks(html)) {
      if (!/\?\s*$/.test(b.heading)) continue;
      const a = (b.body.match(/<p[^>]*>([\s\S]*?)<\/p>/i) || [, ""])[1];
      const ans = stripTags(a);
      if (ans.length >= 20) items.push({ question: b.heading, answer: ans.slice(0, 600) });
    }
  }
  // De-dupe by question; cap.
  const seen = new Set<string>();
  return items.filter((i) => !seen.has(i.question) && seen.add(i.question)).slice(0, 8);
}

/** Testimonials: <blockquote> text with an optional <cite>/<footer> author. */
function detectTestimonials(html: string): Array<{ text: string; author: string }> {
  const out: Array<{ text: string; author: string }> = [];
  for (const m of html.matchAll(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi)) {
    const inner = m[1];
    const author = stripTags((inner.match(/<(?:cite|footer)[^>]*>([\s\S]*?)<\/(?:cite|footer)>/i) || [, ""])[1]);
    const text = stripTags(inner.replace(/<(?:cite|footer)[^>]*>[\s\S]*?<\/(?:cite|footer)>/gi, ""));
    if (text.length >= 24 && text.length < 600) out.push({ text, author: author.slice(0, 80) });
  }
  return out.slice(0, 6);
}

const PRICE_RE = /(?:kr|SEK|€|\$|£)\s?\d[\d\s.,]*|\d[\d\s.,]*\s?(?:kr|:-|SEK|€|\$|£|\/\s?(?:mån|mo|month|månad|tim|hour|h))/i;

/** A heading that is ONLY a price ("575:-", "1 150 kr/tim"). A price table
 *  routinely writes the service in one heading and its price in the next, and
 *  reading that price as a tier NAME produced a table of tiers called "575:-"
 *  with nothing to say what they buy. Seen on a real client site. */
function isPriceOnlyHeading(heading: string): boolean {
  const value = heading.replace(/\s+/g, "").trim();
  if (!value || value.length > 20) return false;
  return /^(?:kr|sek|[€$£])?\d[\d.,]*(?::-|kr|sek|[€$£])?(?:\/(?:mån|månad|tim|h|hour|month|mo))?$/i.test(value);
}

/** Pricing: small headings whose nearby content contains a price token become
 *  tiers. Emitted only with >=2 priced headings (a single price is not a table). */
function detectPricing(html: string): {
  tiers: Array<{ name: string; price: string; features: string[] }>;
} | null {
  const tiers: Array<{ name: string; price: string; features: string[] }> = [];
  const blocks = headingBlocks(html);
  blocks.forEach((b, index) => {
    // Its owner one line above takes it; on its own it is not a tier.
    if (isPriceOnlyHeading(b.heading)) return;
    const next = blocks[index + 1];
    const priced = next && isPriceOnlyHeading(next.heading)
      ? next.heading.trim()
      : (b.heading + " " + stripTags(b.body).slice(0, 240)).match(PRICE_RE)?.[0];
    if (!priced) return;
    const features = [...b.body.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)]
      .map((m) => stripTags(m[1]))
      .filter((t) => t.length > 1 && t.length < 80)
      .slice(0, 6);
    tiers.push({ name: b.heading.slice(0, 60), price: priced.trim().slice(0, 40), features });
  });
  return tiers.length >= 2 ? { tiers: tiers.slice(0, 4) } : null;
}

// Image discovery + role classification lives in `lib/import/imageCandidates.ts`.
// It replaced a local `images()` helper that read `<img src>` only and then
// hard-dropped anything whose filename matched `icon|logo|badge|…`. Three things
// went wrong with that and all three were reported on a real import:
// `srcset`/`<picture>`/lazy-loaded/CSS-background photography was invisible, a
// badge named `iso-9001-2024.png` passed the filename test and - being high in
// the markup - became the hero, and the source's own alt text was discarded.

/** The page's own meta description (`<meta name="description">`, falling back to
 *  `og:description`). Read per PAGE, unlike `extractFromHtml`'s site-level
 *  description, because each page has its own and Google shows each one. */
function metaDescriptionOf(html: string): string | undefined {
  for (const key of ["description", "og:description"]) {
    const k = key.replace(/[:]/g, "\\:");
    const m =
      html.match(
        new RegExp(`<meta[^>]+(?:name|property)=["']${k}["'][^>]*content=["']([^"']*)["']`, "i"),
      ) ??
      html.match(
        new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*(?:name|property)=["']${k}["']`, "i"),
      );
    const value = m?.[1] ? decodeEntities(m[1]) : "";
    if (value) return value;
  }
  return undefined;
}

/** The page's declared canonical, absolutised. Carried so a migrated page keeps
 *  pointing wherever the owner already told search engines it lives; a canonical
 *  we cannot parse is dropped rather than guessed. */
function canonicalOf(html: string, baseUrl: string): string | undefined {
  const href = html.match(
    /<link\b[^>]*\brel=["']?canonical["']?[^>]*\bhref=["']([^"']+)["']/i,
  )?.[1];
  if (!href) return undefined;
  try {
    const abs = new URL(href, baseUrl).toString();
    return /^https?:/i.test(abs) ? abs : undefined;
  } catch {
    return undefined;
  }
}

// ---------------------------------------------------------------------------
// Section types beyond the original nine.
//
// `buildPageSections` emitted a FIXED sequence of nine section types, so 30 of
// the registry's 39 were unreachable from any import - including the ones a
// small-business site is mostly made of. These detectors add the three with the
// highest confidence and the least guessing. Each is gated on structure that is
// actually present (`observeBlock` confirms a real repeat; a keyword alone is
// never enough), so a page without them produces nothing rather than an empty
// band. Deterministic, offline, no AI.
// ---------------------------------------------------------------------------

/** Headings that introduce a list of what the business sells. */
const SERVICES_HEADING =
  /^(tj(ä|a)nster|v(å|a)ra\s+tj(ä|a)nster|vad\s+vi\s+g(ö|o)r|det\s+vi\s+g(ö|o)r|sortiment|utbud|behandlingar|services|our\s+services|what\s+we\s+do|produkter|erbjudande)\b/i;

/** Headings that introduce the step-by-step of working with the business. This
 *  block exists on a large share of trade and service sites and had nowhere to
 *  land: it came in as generic `highlights`, which drops the ordering that is
 *  the entire point of a process section. */
const PROCESS_HEADING =
  /^(s(å|a)\s+g(å|a)r\s+det\s+till|hur\s+(det\s+)?(g(å|a)r\s+det\s+till|fungerar|vi\s+jobbar|vi\s+arbetar)|v(å|a)r\s+process|arbetsg(å|a)ng|steg\s+f(ö|o)r\s+steg|fr(å|a)n\s+ide\s+till|how\s+it\s+works|how\s+we\s+work|our\s+process|the\s+process|step\s+by\s+step|what\s+to\s+expect)\b/i;

/** Headings that introduce the people. */
const TEAM_HEADING =
  /^(teamet|v(å|a)rt\s+team|medarbetare|v(å|a)ra\s+medarbetare|personal|v(å|a)r\s+personal|om\s+personalen|the\s+team|our\s+team|meet\s+the\s+team|staff|anst(ä|a)llda)\b/i;

/** Headings that introduce the places the business travels to. Distinct from
 *  `location` (where they ARE) — a cleaner or a handyman has both. */
const AREAS_HEADING =
  /^(omr(å|a)den?|v(å|a)ra\s+omr(å|a)den|omr(å|a)den\s+vi\s+(jobbar|arbetar)|serviceomr(å|a)den?|var\s+(vi\s+)?(jobbar|arbetar|finns)|vi\s+(jobbar|arbetar)\s+i|orter|st(ä|a)der|areas?\s+we\s+serve|service\s+areas?|where\s+we\s+work)\b/i;

/** Headings that mean "here is where you find us". Used only as the INTENT
 *  signal for a location section — the address itself always comes from what
 *  the page actually declared, never from the heading. */
const FIND_US_HEADING =
  /(hitta\s+(hit|oss)|hitta\s+till\s+oss|bes(ö|o)ksadress|v(å|a)r\s+adress|var\s+finns\s+vi|hos\s+oss|find\s+us|visit\s+us|our\s+address|where\s+to\s+find\s+us|how\s+to\s+find\s+us)/i;

/** A Swedish postcode ("753 20" / "75320"), anywhere in an address line. */
const SWEDISH_POSTCODE = /\b(\d{3}\s?\d{2})\b/;

/** Split the one-line address `extractFromHtml` produces into the structured
 *  shape the `location` section wants. Everything is optional in the validator,
 *  so a line we cannot split cleanly still lands as a street rather than being
 *  thrown away. */
export function splitAddressLine(
  line: string | undefined,
  city: string | undefined,
): { street?: string; postalCode?: string; city?: string } | null {
  const raw = (line ?? "").trim();
  const town = (city ?? "").trim();
  if (!raw && !town) return null;
  const out: { street?: string; postalCode?: string; city?: string } = {};
  let rest = raw;
  const postal = rest.match(SWEDISH_POSTCODE);
  if (postal) {
    out.postalCode = postal[1].replace(/\s+/, " ");
    rest = rest.replace(postal[0], " ");
  }
  // Whatever is left, minus separators and a trailing repeat of the city.
  const street = rest
    .replace(new RegExp(`\\b${town.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "ig"), " ")
    .replace(/[,;]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (street.length >= 3) out.street = street.slice(0, 120);
  if (town) out.city = town.slice(0, 80);
  // A postcode on its own is not an address anyone can navigate to.
  return out.street || out.city ? out : null;
}

/** A "vi jobbar i" list: short place names, not sentences. Gated on a real list
 *  so a paragraph mentioning two towns does not become a section. */
function serviceAreasUnder(html: string): { heading: string; areas: string[] } | null {
  for (const b of sectionsUnderH2(html)) {
    if (!AREAS_HEADING.test(b.heading)) continue;
    const items = [...b.body.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)]
      .map((m) => stripTags(m[1]))
      // A place name is short and has no sentence punctuation in it.
      .filter((t) => t.length >= 2 && t.length <= 40 && !/[.!?:]/.test(t))
      .slice(0, 24);
    const unique = [...new Set(items)];
    if (unique.length >= 3) return { heading: b.heading.slice(0, 80), areas: unique };
  }
  return null;
}

// --- Video embeds ----------------------------------------------------------
// Embeds are the biggest single thing the import tells owners it could not
// bring, and a presentation video is the one embed a small business most often
// has. It is also the one we can carry with zero risk: the `video` section is a
// native, allowlisted YouTube/Vimeo player, so nothing from the source page is
// executed - we take the video id and nothing else.

/** YouTube ids are 11 chars of `[A-Za-z0-9_-]`; Vimeo ids are digits. Anything
 *  else is not an id we are willing to put in an embed URL. */
const YOUTUBE_ID = /^[A-Za-z0-9_-]{11}$/;
const VIMEO_ID = /^\d{6,12}$/;

export type DetectedVideo = { provider: "youtube" | "vimeo"; videoId: string };

/** The first YouTube/Vimeo video the page embeds or links to as a player.
 *  Returns null rather than guessing: a URL we cannot read an id out of is an
 *  embed we could not carry, and the receipt should keep saying so. */
export function detectVideo(html: string): DetectedVideo | null {
  // iframe src first (a real embed), then a bare watch link used as a player.
  const urls = [
    ...[...html.matchAll(/<iframe\b[^>]*\bsrc=["']([^"']+)["']/gi)].map((m) => m[1]),
    ...[...html.matchAll(/https?:\/\/(?:www\.)?(?:youtube\.com|youtu\.be|vimeo\.com)\/[^\s"'<>]+/gi)].map(
      (m) => m[0],
    ),
  ];
  for (const raw of urls) {
    const url = raw.replace(/&amp;/g, "&");
    const yt =
      url.match(/youtube(?:-nocookie)?\.com\/embed\/([^/?&"']+)/i) ??
      url.match(/youtu\.be\/([^/?&"']+)/i) ??
      url.match(/youtube\.com\/watch\?(?:[^"']*&)?v=([^&"']+)/i);
    if (yt && YOUTUBE_ID.test(yt[1])) return { provider: "youtube", videoId: yt[1] };
    const vimeo =
      url.match(/player\.vimeo\.com\/video\/(\d+)/i) ?? url.match(/vimeo\.com\/(\d+)/i);
    if (vimeo && VIMEO_ID.test(vimeo[1])) return { provider: "vimeo", videoId: vimeo[1] };
  }
  return null;
}

// --- Newsletter signup -----------------------------------------------------
// A signup box is one of the few blocks whose MEANING is written into its
// structure: a form whose only field a visitor fills in is an email address is
// a subscribe box, whatever its button says. The source's own contact form
// (name + email + message) and its search box (no email at all) both fail that
// test, which is the point - the discriminator is the field list, never a word
// on the page. Without this the block arrived as a bare `highlights` card
// titled "Nyhetsbrev" with no way to sign up, which is worse than dropping it.

/** Inputs a visitor does not fill in. `hidden` carries list ids, `checkbox`/
 *  `radio` are consent and preferences, and the submit family is the button -
 *  none of them make a form "more than one field". */
const PASSIVE_INPUT = /^(?:hidden|submit|button|image|checkbox|radio|reset)$/i;
/** An input the visitor cannot reach is not a field either. Mailchimp's bot
 *  trap is a `type="text"` input parked off-screen with `tabindex="-1"`, so
 *  counting by type alone made every Mailchimp signup look like a two-field
 *  form and no signup box on the web's most common provider was detected. */
const UNREACHABLE_INPUT = /\btabindex=["']?-1|\baria-hidden=["']?true|\bhidden\b(?![-=])/i;
/** An email field the source did not type as `email`: Webflow and Mailchimp
 *  both ship `type="text" name="EMAIL"`. Matched against the whole attribute
 *  run, so a placeholder ("Din e-post") counts as evidence too. */
const EMAIL_FIELD = /e-?mail|e-?post/i;
/** How far above the form a heading may sit and still be its label. Taking the
 *  nearest preceding heading with no distance gate put "Vanliga frågor" on a
 *  footer signup box. */
const NEWSLETTER_HEADING_REACH = 1200;

export type DetectedNewsletter = { at: number; heading?: string; intro?: string };

/** Where the source's own signup form sat, or null. Exported for the test that
 *  proves a contact form and a search box are NOT one. */
export function detectNewsletterAt(html: string): number | null {
  for (const form of html.matchAll(/<form\b[^>]*>([\s\S]*?)<\/form>/gi)) {
    const body = form[1];
    // A textarea or a select is a message or a choice: that is a contact,
    // booking or quote form, not a subscribe box.
    if (/<(?:textarea|select)\b/i.test(body)) continue;
    let email = 0;
    let other = 0;
    for (const input of body.matchAll(/<input\b([^>]*)>/gi)) {
      const attrs = input[1];
      const type = attrs.match(/\btype=["']?([a-zA-Z]+)/)?.[1] ?? "text";
      if (PASSIVE_INPUT.test(type) || UNREACHABLE_INPUT.test(attrs)) continue;
      if (type.toLowerCase() === "email" || EMAIL_FIELD.test(attrs)) email += 1;
      else other += 1;
    }
    if (email === 1 && other === 0) return form.index ?? 0;
  }
  return null;
}

/** The signup block a source already had: where it sat, plus the words around
 *  it when they are close enough to belong to it. Nothing is invented - a form
 *  with no heading near it gets the product's own default copy, and no intro
 *  sentence at all rather than a guessed one. */
export function detectNewsletter(html: string): DetectedNewsletter | null {
  const at = detectNewsletterAt(html);
  if (at === null) return null;
  // h2-h4 only: an h1 within reach is the page title, not the form's label.
  const heading = [...html.matchAll(/<h([234])[^>]*>([\s\S]*?)<\/h\1>/gi)]
    .map((m) => ({ text: stripTags(m[2]), at: m.index ?? 0 }))
    .filter(
      (h) =>
        h.text.length > 1 &&
        h.text.length <= 80 &&
        h.at < at &&
        at - h.at <= NEWSLETTER_HEADING_REACH,
    )
    .pop();
  const intro = heading
    ? [...html.slice(heading.at, at).matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)]
        .map((m) => stripTags(m[1]))
        .find((text) => text.length >= 20 && text.length <= 300)
    : undefined;
  return {
    at,
    ...(heading ? { heading: heading.text } : {}),
    ...(intro ? { intro } : {}),
  };
}

/** Embeds we actually carried should stop being counted as embeds we lost.
 *  Every `<iframe>` on the page is a dropped embed in the receipt, so importing
 *  the owner's presentation video and then telling them one embed did not come
 *  over is simply wrong. */
function withCarriedEmbeds(
  signals: SourceSignals,
  sections: ReadonlyArray<{ type: string }>,
): SourceSignals {
  const carried = sections.filter((s) => s.type === "video").length;
  return carried > 0 ? { ...signals, embeds: Math.max(0, signals.embeds - carried) } : signals;
}

/** A person's role line under their name ("Snickare", "VD", "Frisör"). Kept
 *  short on purpose: a sentence is a bio, not a job title. */
function looksLikeRole(text: string): boolean {
  return text.length > 1 && text.length <= 40 && !/[.!?]$/.test(text);
}

/**
 * The repeated items inside the block that follows `heading`, as
 * {title, description} pairs.
 *
 * Structure first: `observeBlock` has to see a real repeat with a heading role
 * in each item, otherwise a page that merely mentions "Tjänster" in prose would
 * produce a services section with one bogus card in it.
 */
function sectionsUnderH2(html: string): Array<{ heading: string; body: string }> {
  // Deliberately NOT headingBlocks(): that one stops at the next h1-h4, so an
  // <h2> followed by a grid of <h3> cards got an empty body - which is exactly
  // the shape every services and team block on the web is built from.
  const out: Array<{ heading: string; body: string }> = [];
  const re = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2[\s>]|$)/gi;
  for (const m of html.matchAll(re)) {
    const heading = stripTags(m[1]);
    if (heading.length > 1 && heading.length < 120) out.push({ heading, body: m[2] || "" });
  }
  return out;
}

function repeatedItemsUnder(
  html: string,
  headingTest: RegExp,
): {
  heading: string;
  items: Array<{ title: string; description: string }>;
  shape: ReturnType<typeof observeBlock>;
} | null {
  for (const b of sectionsUnderH2(html)) {
    if (!headingTest.test(b.heading)) continue;
    // Each item is a small heading (h3/h4) plus the copy that follows it, or a
    // list item. Both shapes are extremely common; anything else is left alone.
    const items: Array<{ title: string; description: string }> = [];
    for (const m of b.body.matchAll(
      /<(h[345])[^>]*>([\s\S]*?)<\/\1>([\s\S]*?)(?=<h[1-5][\s>]|$)/gi,
    )) {
      const title = stripTags(m[2]);
      if (title.length < 2 || title.length > 80) continue;
      const para = stripTags((m[3].match(/<p[^>]*>([\s\S]*?)<\/p>/i) ?? [, ""])[1] ?? "");
      items.push({ title: title.slice(0, 80), description: para.slice(0, 400) });
      if (items.length >= 9) break;
    }
    // Two or more sibling headings under one h2 is the repeat. A page that only
    // mentions "Tjänster" in a sentence produces at most one and is left alone.
    if (items.length >= 2) {
      return { heading: b.heading.slice(0, 80), items, shape: observeBlock(b.body) };
    }
  }
  return null;
}

/** The people in a team block: a name, and a short line under it as the role. */
function teamMembersUnder(
  html: string,
): {
  heading: string;
  members: Array<{ name: string; role?: string }>;
  shape: ReturnType<typeof observeBlock>;
} | null {
  const found = repeatedItemsUnder(html, TEAM_HEADING);
  if (!found) return null;
  const members = found.items.map((item) => ({
    name: item.title,
    ...(looksLikeRole(item.description) ? { role: item.description } : {}),
  }));
  return { heading: found.heading, members, shape: found.shape };
}

/** The page's own SEO, read from the document. One implementation for both the
 *  single-page and whole-site paths - the single-page one was missed first time
 *  round, which is exactly the kind of split this avoids. */
function pageSeoFrom(
  html: string,
  url: string,
  suppliedTitle?: string,
): { metaTitle?: string; metaDescription?: string; canonical?: string; sourceUrl: string } {
  const rawTitle =
    suppliedTitle?.trim() ||
    stripTags(html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? "");
  const metaDescription = metaDescriptionOf(html);
  const canonical = canonicalOf(html, url);
  return {
    ...(rawTitle ? { metaTitle: rawTitle.slice(0, 200) } : {}),
    ...(metaDescription ? { metaDescription: metaDescription.slice(0, 400) } : {}),
    ...(canonical ? { canonical } : {}),
    sourceUrl: url,
  };
}

function variantFor(type: string): string {
  const def = (SECTION_REGISTRY as Record<string, { defaultVariant: string } | undefined>)[type];
  return def?.defaultVariant ?? "";
}

type PortableAsset = PortableSiteV1["assets"][number];

/** What a vision model made of each picture, keyed by absolute image URL. Built
 *  by `convex/import/imageRoles.ts`; always optional, because a site must still
 *  import with no model configured. */
export type ImageVerdicts = ReadonlyMap<string, { role: ImageRole; alt?: string }>;

const EMPTY_VERDICTS: ImageVerdicts = new Map();

/** Keep almost the full portable asset allowance for source photography. The
 *  final 20 slots leave room for brand assets or later manual additions while
 *  removing the old arbitrary 60-image truncation on ordinary multi-page
 *  sites. Network bytes and workspace storage remain independently bounded. */
/** Section types that mean "this page's own content is on the page".
 *
 *  DERIVED from the registry, never hand-listed: the first version of this set
 *  was typed out and immediately drifted — it named two types that do not exist
 *  and missed eight that do, so a page that had already been given an `image`
 *  or `scroll-tabs` band could still take the last-resort path below and gain a
 *  second band saying the same thing. Hero, contact and footer are the chrome
 *  every imported page gets, so they do not count as the page speaking. */
const CONTENT_BANDS: ReadonlySet<string> = new Set(
  Object.keys(SECTION_REGISTRY).filter((type) => !["hero", "contact", "footer"].includes(type)),
);

const MAX_IMPORT_ASSETS = 180;

/** How much of the opening paragraph the hero shows. Named because About reads
 *  it too: a paragraph longer than this is only partly shown by the hero, so
 *  About keeps it rather than treating it as already told. */
const HERO_SUBHEADLINE_CHARS = 200;

/** Dedupes images by source URL across every page of a multi-page import and
 *  hands out stable export ids. One image linked from three pages uploads once
 *  and every referencing section points at the same asset. */
class AssetRegistry {
  private byUrl = new Map<string, string>();
  readonly assets: PortableAsset[] = [];
  /** How many distinct images were skipped because the cap was hit - surfaced in
   *  the import summary so truncation is never silent ("imported 60 of 74"). */
  droppedCount = 0;

  /** Register an image URL, returning its export id — or null once the global
   *  cap is hit, so callers simply skip the image. */
  register(url: string, alt: string): string | null {
    const existing = this.byUrl.get(url);
    if (existing !== undefined) return existing || null; // "" = already-dropped
    if (this.assets.length >= MAX_IMPORT_ASSETS) {
      this.byUrl.set(url, ""); // remember we saw it, so the count is distinct
      this.droppedCount++;
      return null;
    }
    const id = `img${this.assets.length}`;
    this.byUrl.set(url, id);
    this.assets.push({
      exportId: id,
      url,
      width: 1600,
      height: 1066,
      mimeType: mimeFromUrl(url),
      kind: "image",
      alt,
    });
    return id;
  }

  /**
   * Register a downloadable PDF (the `documents` section's assetRef).
   *
   * Shares the image cap deliberately - it is one outbound-fetch budget, and a
   * page linking eighty PDFs should not be able to starve its own photography.
   * `width`/`height` are 0 because a document has no layout box; the commit
   * path (`convex/portability.ts`) byte-sniffs `%PDF-` and drops anything that
   * is not really a PDF, so a wrong `mimeType` here can only ever lose the
   * file, never smuggle one in.
   */
  registerDocument(url: string, title: string): string | null {
    const existing = this.byUrl.get(url);
    if (existing !== undefined) return existing || null;
    if (this.assets.length >= MAX_IMPORT_ASSETS) {
      this.byUrl.set(url, "");
      this.droppedCount++;
      return null;
    }
    const id = `doc${this.assets.length}`;
    this.byUrl.set(url, id);
    this.assets.push({
      exportId: id,
      url,
      width: 0,
      height: 0,
      mimeType: "application/pdf",
      kind: "document",
      alt: title,
    });
    return id;
  }
}

/**
 * A human label from a file name: `iso-9001-2024.png` → "Iso 9001 2024".
 * Used only where the section model REQUIRES a label and the source gave no alt
 * (certification and partner strips). A file name that carries no letters at
 * all - a hash, a numeric id - yields "" and the item is dropped instead of
 * shown with a meaningless caption.
 */
function labelFromFilename(url: string): string {
  const base = (url.split("?")[0].split("#")[0].split("/").pop() ?? "")
    .replace(/\.[a-z0-9]+$/i, "")
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!/[a-zA-ZåäöÅÄÖ]{2}/.test(base)) return "";
  // Drop the responsive-variant suffixes builders append ("-1024x768", "@2x").
  const cleaned = base.replace(/\s*\d{2,4}x\d{2,4}\s*$/i, "").replace(/@\d+x$/i, "").trim();
  return cleaned ? cleaned.charAt(0).toUpperCase() + cleaned.slice(1) : "";
}

/** Nominal mime from the URL's extension. The real one is decoded at commit
 *  time (`downloadAndCommit`); this only has to be honest enough that an SVG is
 *  not announced as a JPEG - a site logo is very often an SVG, and the commit
 *  path screens SVGs on a different route from rasters. */
function mimeFromUrl(url: string): string {
  const ext = (url.split("?")[0].split("#")[0].match(/\.([a-z0-9]+)$/i)?.[1] ?? "").toLowerCase();
  switch (ext) {
    case "svg":
      return "image/svg+xml";
    case "png":
      return "image/png";
    case "webp":
      return "image/webp";
    case "avif":
      return "image/avif";
    case "gif":
      return "image/gif";
    default:
      return "image/jpeg";
  }
}

/**
 * The business's own logo, taken from the page header.
 *
 * The URL import never set `site.logoAssetId`, so every migrated site arrived
 * with no logo at all and the owner had to find and re-upload it - on a site we
 * had just downloaded it from. The header's first brand mark is the logo on
 * essentially every small-business page; anything further down is a partner's.
 */
function siteLogoFrom(
  html: string,
  baseUrl: string,
  registry: AssetRegistry,
  businessName: string,
): string | undefined {
  const inHeader = imageCandidates(html, baseUrl).filter(
    (c) => c.region === "header" || c.region === "nav",
  );
  const logo =
    inHeader.find((c) => c.guess === "logo") ??
    // A header that declared no region-level mark but whose only image is an
    // SVG icon: still the logo, since nothing else in a header ever is.
    inHeader.find((c) => c.guess === "icon" && /\.svg(\?|#|$)/i.test(c.url));
  if (!logo) return undefined;
  return registry.register(logo.url, logo.alt || businessName) ?? undefined;
}

type BuiltSection = {
  type: PortableSiteV1["sections"][number]["type"];
  content: unknown;
  /** Optional variant override (else the section type's default is used). */
  variant?: string;
  /** Byte offset in the source HTML of the evidence this section was built
   *  from. It is what lets an imported page keep the ORDER the owner chose -
   *  see `inSourceOrder`. Absent means "the source had no position for this",
   *  which is true of the contact form we add and of schema.org opening hours. */
  at?: number;
  /** Position in the DETECTOR ladder, before source-order sorting. It is what
   *  `externalKey` is built from, and it must stay independent of the rendered
   *  order: a re-sync (`portability.importWholeSite({ mergeIntoWebsiteId })`)
   *  matches an existing site's sections by that key and updates them in place.
   *  Keying on the rendered position instead would mean a site imported before
   *  source ordering existed could have its gallery quietly overwritten with a
   *  pricing table the next time the owner synced. */
  ladder?: number;
};

/**
 * Put a page's sections back into the order the SOURCE had them in.
 *
 * The importer used to emit a fixed ladder — hero, about, video, services,
 * team, process, areas, highlights, pricing, testimonials, faq, gallery,
 * location, hours, contact — regardless of how the original page was laid out.
 * Every detector was individually right and the result was still somebody
 * else's website: a shop that led with its prices got them below a gallery, a
 * studio that opened with its work got a wall of text first. It is the single
 * biggest reason an import "looks nothing like the original" (owner report,
 * 2026-08-07).
 *
 * Fixed points, because these are ours rather than the source's:
 *   • the hero is the top of the page by definition;
 *   • the contact form and footer are appended by us and stay last.
 * Everything between is sorted by where its evidence actually appeared. A
 * section with no offset keeps its ladder position relative to its neighbours
 * (a stable sort over the original index), so nothing is ever moved on a guess.
 */
/** Every heading in the document with where it sat, so a paragraph can be
 *  attributed to the block it belongs to. */
function headingsAt(html: string): Array<{ text: string; at: number }> {
  const out: Array<{ text: string; at: number }> = [];
  for (const m of html.matchAll(/<h([1-4])[^>]*>([\s\S]*?)<\/h\1>/gi)) {
    const text = stripTags(m[2]);
    if (text.length > 1 && text.length < 160) out.push({ text, at: m.index ?? 0 });
  }
  return out;
}

/** Comparison key for a paragraph: enough of it to be certain, loose enough to
 *  survive a detector's own truncation (FAQ answers are cut at 600 chars).
 *
 *  One implementation, shared with `structureDetect`: the rich-text detector
 *  decides what is already claimed using the same set this builds, and two
 *  copies of the rule drifting is how a sentence lands on two sections. */
const textKey = proseKey;

/** Every run of prose the sections built so far already show, so About does not
 *  repeat it. Walks the content objects rather than naming fields per section
 *  type, so a new detector is covered the day it is added. */
function claimedText(built: BuiltSection[]): Set<string> {
  const out = new Set<string>();
  const walk = (value: unknown) => {
    if (typeof value === "string") {
      if (value.length >= 40) out.add(textKey(value));
      return;
    }
    if (Array.isArray(value)) {
      for (const v of value) walk(v);
      return;
    }
    if (value && typeof value === "object") {
      for (const v of Object.values(value)) walk(v);
    }
  };
  for (const section of built) walk(section.content);
  return out;
}

function inSourceOrder(input: BuiltSection[]): BuiltSection[] {
  const TAIL: ReadonlySet<string> = new Set(["contact", "footer"]);
  // Stamp the ladder position BEFORE any reordering; see `ladder` above.
  const built = input.map((b, i) => ({ ...b, ladder: i }));
  const head = built.filter((b) => b.type === "hero");
  const tail = built.filter((b) => TAIL.has(b.type));
  const middle = built.filter((b) => b.type !== "hero" && !TAIL.has(b.type));
  const positioned = middle
    .map((b, i) => ({ b, i }))
    // An unpositioned section sorts as if it sat where the ladder put it,
    // between its positioned neighbours rather than at either end.
    .sort((x, y) => {
      const ax = x.b.at ?? Number.POSITIVE_INFINITY;
      const ay = y.b.at ?? Number.POSITIVE_INFINITY;
      return ax - ay || x.i - y.i;
    })
    .map((x) => x.b);
  return [...head, ...positioned, ...tail];
}

// Heading families that read as serif -> the imported site keeps a serif feel
// via a serif fontPair; everything else maps to the clean grotesk `modern`.
const SERIF_HINT =
  /serif|georgia|times|playfair|merriweather|lora|cormorant|garamond|fraunces|spectral|baskerville|crimson|recoleta|slab|noto serif|source serif|dm serif|pt serif|calluna|freight|tiempos|canela|chronicle|minion|sabon|caslon|didot|bodoni|utopia|charter|lyon|reckless|gt sectra/i;

/** Map an extracted hero layout onto a real hero variant key. */
function heroVariantFor(layout: HeroLayout): string {
  return layout; // image-right | image-left | centered | overlay are all valid keys
}

// A CONDENSED face is the one width the two defaults cannot express, and it is
// the most visible thing to get wrong: a page whose headings are set in DIN
// Condensed and rebuilt in Inter is not a near miss, it is a different design —
// wider, quieter, and about 30% more line length for the same words. Any name
// carrying a narrow/condensed marker, plus the condensed faces that are famous
// enough to be named outright, resolve to the curated condensed family.
const CONDENSED_HINT =
  /\b(condensed|cond|narrow|compressed|extended-?narrow)\b|^din\b|din[ -]?(next|pro|condensed)|bebas|anton|oswald|united sans|knockout|trade gothic|impact|haettenschweiler/i;
const CONDENSED = findGoogleFont("Barlow Condensed")!;

const DEFAULT_SANS = findGoogleFont("Inter")!;
// Lora is a calm text serif - a closer fallback for body serifs (Calluna,
// Tiempos, Freight...) than a high-contrast display face.
const DEFAULT_SERIF = findGoogleFont("Lora")!;

/** Resolve an extracted family name to a CURATED Google font so it can actually
 *  be loaded (source "google" requires an allow-listed family, and only a
 *  loaded @font-face renders). Exact match wins; then the nearest curated face
 *  by WIDTH, then by serif/sans category.
 *
 *  This runs for every family a source page names, including the ones it loads
 *  from its own Adobe Fonts kit. Registering those against the kit under their
 *  real names was tried and reverted 2026-08-08: Adobe's terms require a site to
 *  load its fonts through the account that subscribes to them and do not permit
 *  serving them through anyone else's, so there is nothing this product could
 *  hold centrally that would make them render here. The site got a system
 *  fallback instead — further from the source than the nearest curated face,
 *  with nothing in the theme to swap. Substituting puts it on the receipt
 *  (`FontMatch.substituted`) and gives the refine panel its "upload the real
 *  file" button, which is the route that works for an owner who holds the
 *  licence. */
function resolveFont(family: string): GoogleFont {
  const exact = findGoogleFont(family);
  if (exact) return exact;
  // Case-insensitive match against the curated list.
  const ci = GOOGLE_FONTS.find((f) => f.family.toLowerCase() === family.toLowerCase());
  if (ci) return ci;
  // Width before category: a condensed SERIF is rarer than a condensed grotesk,
  // and reading a condensed name as "serif" would land it on Lora, which is the
  // one thing it certainly is not.
  if (CONDENSED_HINT.test(family)) return CONDENSED;
  return SERIF_HINT.test(family) ? DEFAULT_SERIF : DEFAULT_SANS;
}

export type ImportFonts = {
  fonts: PortableSiteV1["fonts"];
  fontsAssignment: PortableSiteV1["fontsAssignment"];
  heading: string;
  body: string;
  /** Third role, present only when the source page actually used a third
   *  typeface (a display cut on the h1 distinct from the section headings). */
  display?: string;
};

/** Real Google-font entries + assignment for an imported site's typefaces, so
 *  the migrated site LOADS the same (or nearest curated) fonts, not just names
 *  them. Deduped when heading and body resolve to the same family. */
export function importFonts(design: ExtractedDesign): ImportFonts {
  const headingFam = design.fonts.heading || "";
  const bodyFam = design.fonts.body || headingFam;
  const heading = headingFam ? resolveFont(headingFam) : DEFAULT_SANS;
  const body = bodyFam ? resolveFont(bodyFam) : DEFAULT_SANS;
  const fonts: PortableSiteV1["fonts"] = [];
  const idFor = (family: string) => `font-${family.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  // EVERY role ships a curated Google family, including the ones the source
  // loaded from its own Adobe Fonts kit.
  //
  // Registering those against the kit under their real names shipped on
  // 2026-08-02 and was reverted on 2026-08-08 (owner directive: "I can't access
  // that web project — use the closest alternative fonts").
  //
  // The obstacle is the LICENCE, not a setting, and the first version of this
  // comment had that wrong. Adobe's terms require a site to load its fonts
  // through the account that subscribes to them and do not permit serving them
  // through another person's subscription — so there is no key, kit or account
  // we could hold centrally and point every customer site at, however the
  // hosting is arranged.
  //
  // A CURRENT Adobe web project is not domain-locked at all: its embed code
  // works on any hostname. That is worse for us, not better — a central kit
  // would quietly WORK while breaching the terms on every site it served, and
  // one lapsed subscription would take every customer's typography down at
  // once. The allow-list this code used to describe is a legacy Typekit
  // concept, which is why the reference site's fonts failed on a preview.
  //
  // What the owner got was a system fallback — further from their source than
  // the nearest curated face, with no font in the theme to swap and nothing to
  // upload against.
  //
  // Substituting instead puts the swap on the receipt (`FontMatch.substituted`)
  // and gives the refine panel its "upload the real file" row, which is the one
  // route that actually works for an owner who holds the licence. The kit is
  // still detected and still reported (`adobe_fonts_kit` in importActions), so
  // nothing is hidden — it just no longer decides what the site loads.
  //
  // One portable font entry per DISTINCT family, so three roles that resolve to
  // two families still register two fonts.
  const registered = new Map<string, string>();
  const register = (family: string): string => {
    const existing = registered.get(family);
    if (existing) return existing;
    const id = idFor(family);
    registered.set(family, id);
    fonts.push({ tmpId: id, source: "google", family });
    return id;
  };
  const headingId = register(heading.family);
  const bodyId = register(body.family);
  // Only when the source really had a third face. `resolveFont` snaps an
  // unknown family to a curated default, so a display face that resolves to the
  // same family as the heading is not a third role - it is the same font.
  const displayFam = design.fonts.display;
  const display = displayFam ? resolveFont(displayFam) : undefined;
  const displayId =
    display && display.family !== heading.family ? register(display.family) : undefined;
  return {
    fonts,
    fontsAssignment: {
      headingTmpId: headingId,
      bodyTmpId: bodyId,
      ...(displayId ? { displayTmpId: displayId } : {}),
    },
    heading: heading.family,
    body: body.family,
    ...(displayId && display ? { display: display.family } : {}),
  };
}

/** Build theme tokens from an imported page's design signals: the brand colour
 *  becomes a `customPalette`, the resolved typefaces become `customFonts` (plus
 *  the nearest built-in `fontPair` as fallback), and radius/density carry over.
 *  This is what makes an imported site read as "my site" not a template. */
export function themeFromDesign(
  design: ExtractedDesign,
  fonts: ImportFonts,
  /** True when the source page actually animated (GSAP/AOS/Webflow/…). The
   *  imported site then gets SnabbSajt's own scroll motion instead of landing
   *  completely still - the source's real animations can't come over, but
   *  "your site used to move and now it doesn't" is the wrong default. A still
   *  source stays still. */
  sourceHadMotion = false,
): ThemeTokens {
  const headingIsSerif = SERIF_HINT.test(design.fonts.heading);
  const fontPair: ThemeTokens["fontPair"] = headingIsSerif ? "classic" : "modern";
  return {
    palette: "slate", // fallback if customPalette is ever dropped/sanitized out
    fontPair,
    density: design.density,
    radius: design.radius,
    buttonStyle: "solid",
    // A page whose animation we actually READ gets `full`, not `subtle`: full
    // is the step that staggers a band's children, which is what every one of
    // these sources does (GSAP `stagger`, IX2's per-item delays). `subtle`
    // stays the answer for a page we only know MOVED, from a library tag.
    ...(design.motion
      ? { motion: "full" as const, customMotion: design.motion }
      : sourceHadMotion
        ? { motion: "subtle" as const }
        : {}),
    customPalette: design.palette,
    customFonts: {
      heading: fonts.heading,
      body: fonts.body,
      ...(fonts.display ? { display: fonts.display } : {}),
    },
    ...(design.brand?.hex ? { customBrandHex: design.brand.hex } : {}),
    // The source's own header treatment. Absent for a page whose header sits in
    // the flow, which is every site that has not asked for the overlay.
    ...(design.navOverlay ? { navOverlay: design.navOverlay } : {}),
    ...measuredTheme(design, !!fonts.display),
  };
}

/** The measured half of an imported theme: per-role type and section/container
 *  layout, read off the RENDERED source page (`applyComputedSample`). Absent
 *  whenever the import had no render step, in which case the site keeps the
 *  preset type scale exactly as every import did before this existed. */
function measuredTheme(
  design: ExtractedDesign,
  hasDisplayFont: boolean,
): Pick<ThemeTokens, "customType" | "customLayout"> {
  const out: Pick<ThemeTokens, "customType" | "customLayout"> = {};
  if (design.type && Object.keys(design.type).length > 0) {
    const customType: NonNullable<ThemeTokens["customType"]> = { ...design.type };
    if (hasDisplayFont) {
      // The h1's typeface became the DISPLAY role (see applyComputedSample), so
      // the two roles drawn from the h1 have to point at it - otherwise the
      // hero renders in the section-heading face and the third font is loaded
      // but never used.
      customType.display = { ...customType.display, family: "display" };
      customType.h1 = { ...customType.h1, family: "display" };
    }
    out.customType = customType;
  }
  if (design.layout && Object.keys(design.layout).length > 0) {
    out.customLayout = design.layout;
  }
  return out;
}

/** Approximate one HTML page onto the constrained section model. Images are
 *  registered in the shared `registry` so exportIds are global (cross-page
 *  dedup). Returns the ordered sections for this page only. */
function buildPageSections(
  html: string,
  baseUrl: string,
  locale: "sv" | "en",
  registry: AssetRegistry,
  heroVariant?: string,
  /** Optional vision verdicts, keyed by absolute image URL. Absent (no model
   *  configured, or the pass failed) leaves the deterministic classification
   *  in place - see `applyVerdicts`. */
  verdicts?: ImageVerdicts,
): BuiltSection[] {
  const meta = extractFromHtml(html, baseUrl);
  const t = COPY[locale];
  const name = (meta.businessName?.trim() || headings(html, "h1")[0] || t.heroFallback).slice(0, 120);
  const paras = paragraphs(html);
  const description = meta.description?.trim() || paras[0];
  // Every picture the page shows, classified. `rankedPhotos` drops furniture
  // (logos, badges, icons, texture) and orders what is left by how likely it is
  // to be the subject of the page - explicitly NOT by document order, which is
  // what used to put a certification badge in the hero.
  const candidates = applyVerdicts(imageCandidates(html, baseUrl), verdicts ?? EMPTY_VERDICTS);
  // Detected here, before the photo pool is ranked, because both bands OWN
  // their pictures and the pool must never have offered them elsewhere. An
  // Instagram thumbnail is not this business's hero and it is not the picture
  // beside their story - but `rankedPhotos` cannot know that, so the first
  // wiring of these detectors put a 320px feed thumbnail in the About section
  // AND left it in the Instagram grid, the same photo twice on one page.
  const bento = detectBento(html, baseUrl);
  const instagram = detectInstagram(html, baseUrl);
  // A before/after pair owns BOTH its pictures, and for a sharper reason than
  // the other picture-owning bands: the relationship IS the content. Let the
  // pool take them and the page shows two unexplained photos of the same
  // bathroom, which is what every import of a salon or a bygg site did until
  // now — the source's whole point, thrown away at the last step.
  const beforeAfter = detectBeforeAfter(html, baseUrl);
  const ranked = rankedPhotos(candidates);
  // Pictures the SOURCE grouped as a gallery. An explicit grouping outranks our
  // ranking for one decision only — which photo the hero takes — because the
  // hero used to eat a member of a three-picture gallery, leaving two, which is
  // one short of a gallery: the band vanished and the third photo was reported
  // as never referenced. Verified on a real salon page.
  const galleryGroup = detectGalleryGroup(html, baseUrl);
  // A captioned <figure> is owned the same way, and for the same reason: the
  // caption is the source telling us this picture carries meaning, and every
  // band that could otherwise take it - hero, About, gallery - stores the
  // picture and throws the words away. The hero is the one exception: a
  // captioned hero image is still the hero, and demoting the page's opening
  // photo to a mid-page figure is a bigger loss than one caption.
  const captioned = detectCaptionedImages(html, baseUrl).filter((f) => f.url !== ranked[0]?.url);
  const ownedUrls = new Set<string>([
    ...(bento?.cells.map((c) => c.imageUrl).filter((u): u is string => !!u) ?? []),
    ...(instagram?.imageUrls ?? []),
    ...captioned.map((f) => f.url),
    ...(beforeAfter?.pairs.flatMap((p) => [p.beforeUrl, p.afterUrl]) ?? []),
  ]);
  const photos = (() => {
    const free = ranked.filter((c) => !ownedUrls.has(c.url));
    if (!galleryGroup) return free;
    const grouped = new Set(galleryGroup);
    const loose = free.filter((c) => !grouped.has(c.url));
    const inGroup = free.filter((c) => grouped.has(c.url));
    // Loose photos first, so the hero takes one of those and the group stays
    // whole. Below three the group is not a gallery anyway and the old order
    // stands.
    return inGroup.length >= 3 ? [...loose, ...inGroup] : free;
  })();
  /** True when every photograph on the page belongs to the source's gallery.
   *  Then the hero goes text-only: three pictures the owner grouped beat a hero
   *  photo plus two orphans, and the same picture must not appear twice. */
  const heroYieldsToGallery =
    galleryGroup !== null &&
    ranked.filter((c) => !ownedUrls.has(c.url) && !new Set(galleryGroup).has(c.url)).length === 0 &&
    ranked.filter((c) => !ownedUrls.has(c.url)).length >= 3;
  // Each image keeps the alt the SOURCE wrote. Falling back to the business name
  // on every image (the old behaviour) is worse than useless for a screen
  // reader: it says the same thing eight times and describes none of them.
  const registered = photos
    .map((c) => ({
      id: registry.register(c.url, c.alt || name),
      alt: c.alt,
      at: c.docOffset,
    }))
    .filter((r): r is { id: string; alt: string; at: number } => r.id !== null);
  const imageIds = registered.map((r) => r.id);
  /** The alt to render for an image, so a section never re-labels a picture the
   *  author already described. */
  const altOf = (id: string): string =>
    registered.find((r) => r.id === id)?.alt || name;
  /** Where a registered picture sat, so a gallery lands where the source's
   *  pictures were rather than at a fixed rung of the ladder. */
  const offsetOf = (id: string | undefined): number | undefined =>
    id === undefined ? undefined : registered.find((r) => r.id === id)?.at;

  const built: BuiltSection[] = [];

  // A policy page is a DOCUMENT, not a marketing page with bands on it. Run
  // before anything else and return: putting the ordinary detectors over an
  // integritetspolicy built a "Det vi gör" highlights grid out of its clause
  // headings and an "Om oss" wall out of its prose, which is both wrong and
  // unreadable. `legal` is the one section type that holds long structured
  // prose, and this is what it is for.
  const legal = detectLegal(html);
  if (legal) {
    return [
      { type: "legal", content: { type: "legal", heading: legal.heading, blocks: legal.blocks } },
      { type: "footer", content: { type: "footer", businessName: name } },
    ];
  }

  /** Where a heading the detectors returned actually sat in the document, so a
   *  section can be put back where the owner had it. `undefined` when the text
   *  cannot be located (entities, whitespace), which the sorter treats as "no
   *  position" rather than "position zero". */
  const atOfHeading = (heading: string | undefined): number | undefined => {
    if (!heading) return undefined;
    const at = html.indexOf(heading.slice(0, 40));
    return at >= 0 ? at : undefined;
  };
  const paraAt = paragraphsAt(html);
  const atOfParagraph = (text: string | undefined): number | undefined =>
    text === undefined ? undefined : paraAt.find((p) => p.text === text)?.at;

  // Hero - name + tagline + first image. Variant mirrors the source layout
  // (image-left/right/centered/overlay) so the imported hero feels familiar; a
  // source with no hero image falls back to a text-only "centered" hero.
  const heroImageId = heroYieldsToGallery ? undefined : imageIds[0];
  built.push({
    type: "hero",
    variant: heroImageId ? heroVariant : "centered",
    content: {
      type: "hero",
      headline: name,
      ...(description ? { subheadline: description.slice(0, HERO_SUBHEADLINE_CHARS) } : {}),
      ...(heroImageId ? { media: { assetId: heroImageId, alt: altOf(heroImageId) } } : {}),
    },
  });

  // About - a second substantial paragraph, if any.
  //
  // The variant has to follow the picture, not the other way round. `about`
  // defaults to `text-image`, so leaving the variant unset shipped a two-column
  // layout with an empty image well on every imported site that had only one
  // usable photo - the hero had taken it. Verified 2026-07-27 on a real import:
  // the home page rendered a text-image About beside nothing at all.
  // ALL the owner's prose, not one paragraph of it. `paras.find` kept exactly
  // one and discarded the rest, so a page with five paragraphs about the
  // business imported one - the single biggest reason an imported site "feels
  // gutted" to its owner. Joined in page order, bounded, and de-duplicated
  // against the hero's subheadline so the same sentence is not shown twice.
  // The hero SHOWS 200 characters of the opening paragraph. When that paragraph
  // is longer than the hero can show, excluding it from About discards the rest
  // of it: a page whose only prose is one 4 000-character "om verksamheten"
  // block imported as a 200-character hero line and nothing else, with no
  // finding to say so. Above the hero's own cap the paragraph stays in the
  // About pool, and the leading duplicate is the price of not losing the tail.
  const aboutParas = paras.filter((p) => p !== description || p.length > HERO_SUBHEADLINE_CHARS);
  // Whether About gets a picture is decided here, with the gallery, because the
  // two share one pool. WHAT About says is decided at the end of this function,
  // once every other detector has taken its own text - see `aboutBody` below.
  const aboutBody = aboutParas.length ? "pending" : undefined;
  // Which photo About gets, decided against the gallery rather than in isolation
  // - the two share one pool. The hero has already taken imageIds[0].
  //
  //   0 left  -> About is text-only (that is the whole point of this change).
  //   1-2     -> a gallery cannot form (it needs 3), so those photos would go
  //              unused; About takes one.
  //   3       -> exactly one gallery. About takes none rather than breaking it.
  //   4+      -> About takes the LAST, so the gallery keeps a contiguous run of
  //              at least 3 and no photo appears twice on the page.
  const galleryPool = heroYieldsToGallery ? imageIds : imageIds.slice(imageIds[0] ? 1 : 0);
  const aboutImage = !aboutBody
    ? undefined
    : galleryPool.length <= 2
      ? galleryPool[0]
      : galleryPool.length >= 4
        ? galleryPool[galleryPool.length - 1]
        : undefined;


  // Video - the one embed we can carry without executing anything from the
  // source. `video` is a native allowlisted YouTube/Vimeo player, so we take
  // the id and nothing else. Everything else in an <iframe> is still dropped,
  // and the receipt still says so.
  const video = detectVideo(html);
  const atOfVideo = (() => {
    const m = html.match(/<iframe[^>]*>/i);
    return m?.index;
  })();
  if (video) {
    built.push({
      type: "video",
      at: atOfVideo,
      content: { type: "video", heading: t.video, ...video },
    });
  }

  // Highlights - a section heading plus the copy that FOLLOWS it. The cards used
  // to ship `description: ""` on every item, so an imported site presented a row
  // of bare titles and the owner had to retype text that was on their old page a
  // paragraph below the heading we took. `headingBlocks` already pairs each
  // heading with its following markup; this reads the first paragraph out of it.
  // Services - the list of what they sell, when the page really has one. Takes
  // precedence over `highlights` for those headings: a card grid of service
  // names IS the services section, and importing it as generic "highlights" was
  // the single most visible way an imported site looked less capable than the
  // original.
  const services = repeatedItemsUnder(html, SERVICES_HEADING);
  if (services) {
    built.push({
      type: "services",
      at: atOfHeading(services.heading),
      // The layout the source actually used, rather than the registry default:
      // a two-item list reads as a list, a wide grid as a grid, and a block the
      // page scrolls sideways keeps its card feel.
      variant:
        services.items.length === 2
          ? "grid-2"
          : services.shape.media === "many"
            ? "split"
            : "grid-3",
      content: {
        type: "services",
        heading: services.heading,
        items: services.items.map((item) => ({
          title: item.title,
          description: item.description,
        })),
      },
    });
  }

  // Team - the people. Names only unless the line under a name is short enough
  // to be a job title rather than a sentence.
  const team = teamMembersUnder(html);
  if (team) {
    built.push({
      type: "team",
      at: atOfHeading(team.heading),
      variant: team.shape.media === "many" ? "cards" : "grid",
      content: {
        type: "team",
        heading: team.heading,
        members: team.members,
      },
    });
  }

  // Process - "Så går det till" / "How it works". Same structural gate as
  // services and team (a real repeat under the heading, never a keyword alone).
  // Without this the block arrived as generic `highlights`, which throws away
  // the ordering that is the whole reason the section exists.
  const process = repeatedItemsUnder(html, PROCESS_HEADING);
  if (process) {
    built.push({
      type: "process",
      at: atOfHeading(process.heading),
      // Three steps read as a row; more than that stacks better than it wraps.
      variant: process.items.length <= 3 ? "steps-horizontal" : "steps-vertical",
      content: {
        type: "process",
        heading: process.heading,
        steps: process.items.map((item) => ({
          title: item.title,
          description: item.description,
        })),
      },
    });
  }

  // Service areas - the towns a mobile trade travels to. A list, never prose:
  // "vi jobbar i Uppsala och Enköping" in a sentence stays a sentence.
  const areas = serviceAreasUnder(html);
  if (areas) {
    built.push({
      type: "service-areas",
      at: atOfHeading(areas.heading),
      content: { type: "service-areas", heading: areas.heading, areas: areas.areas },
    });
  }

  // Titles stay h2-only (h3/h4 are sub-points, and a "?" heading is an FAQ item
  // that already has its own section), but each one now carries the paragraph
  // that followed it on the source page.
  // Newsletter - the source's own signup box, kept as one. Built before the
  // heading bookkeeping below so its heading is claimed: left in the pool it
  // came back a second time as an empty "Nyhetsbrev" highlights card.
  const newsletter = detectNewsletter(html);
  if (newsletter) {
    built.push({
      type: "newsletter",
      at: newsletter.at,
      content: {
        type: "newsletter",
        heading: newsletter.heading ?? t.newsletter,
        ...(newsletter.intro ? { intro: newsletter.intro } : {}),
        placeholder: t.newsletterPlaceholder,
        submitLabel: t.newsletterSubmit,
        successMessage: t.newsletterSuccess,
      },
    });
  }

  // --- The nine detectors added for backlog 1725 item 10 -------------------
  // All of them run BEFORE the h2 pool below, for the same reason the
  // newsletter does: a heading left in the pool comes back a second time as an
  // empty highlights card under the section that already used it.

  // Announcement strip. Structural (role/class), never position - "the first
  // div in the body" is the header on most sites.
  const banner = detectBanner(html, baseUrl);
  if (banner) {
    built.push({
      type: "banner",
      at: banner.at,
      content: {
        type: "banner",
        text: banner.text,
        ...(banner.ctaUrl && banner.ctaLabel
          ? {
              cta: {
                label: banner.ctaLabel,
                target: { kind: "external" as const, url: banner.ctaUrl },
              },
            }
          : {}),
      },
    });
  }

  // Downloadable PDFs. An item whose file we could not carry is dropped by
  // `sanitizeAfterRemap`, and the band with it if nothing is left - a title
  // with nothing behind it is a section that lies about having a file.
  const documents = detectDocuments(html, baseUrl);
  if (documents) {
    const items = documents.items
      .map((item) => {
        const id = registry.registerDocument(item.url, item.title);
        return id ? { title: item.title, document: { assetId: id, alt: item.title } } : null;
      })
      .filter((i): i is NonNullable<typeof i> => i !== null);
    if (items.length > 0) {
      built.push({
        type: "documents",
        at: documents.at,
        content: {
          type: "documents",
          heading: documents.heading ?? t.documents,
          items,
        },
      });
    }
  }

  // A booking system the source linked to or framed. The URL only: the
  // renderer derives the provider, exactly as it does for a link the owner
  // pastes - the source's own widget markup is evidence, never runtime.
  const booking = detectBooking(html, baseUrl);
  if (booking) {
    built.push({
      type: "booking",
      at: booking.at,
      content: {
        type: "booking",
        heading: booking.heading ?? t.booking,
        source: {
          kind: "provider" as const,
          url: booking.url,
          ...(booking.ctaLabel ? { ctaLabel: booking.ctaLabel } : {}),
        },
      },
    });
  }

  // A real <table> comparison. A CSS grid that merely looks like one is left
  // alone: it cannot be told from a pricing or services grid without computed
  // styles, and both of those already have a better home.
  const comparison = detectComparison(html);
  if (comparison) {
    built.push({
      type: "comparison",
      at: comparison.at,
      content: {
        type: "comparison",
        heading: comparison.heading ?? t.comparison,
        columns: comparison.columns.map((label) => ({ label })),
        rows: comparison.rows,
      },
    });
  }

  // One detected button as the section model's own CTA. The detector already
  // sorted it into a target kind, so a "Ring oss" button stays a phone target
  // instead of being flattened into an https URL it would fail validation as.
  const ctaAction = (a: DetectedCtaAction) => ({
    label: a.label,
    target:
      a.kind === "phone"
        ? ({ kind: "phone" as const, value: a.value })
        : a.kind === "email"
          ? ({ kind: "email" as const, value: a.value })
          : ({ kind: "external" as const, url: a.url }),
  });

  // The closing ask. Emitted from the source's own band rather than added on
  // our initiative: a `cta-band` we invented would be this software making the
  // owner's offer for them, and the import's whole contract is that a section
  // exists because the source had one.
  const ctaBand = detectCtaBand(html, baseUrl);
  if (ctaBand) {
    built.push({
      type: "cta-band",
      at: ctaBand.at,
      content: {
        type: "cta-band",
        headline: ctaBand.headline,
        ...(ctaBand.subtext ? { subtext: ctaBand.subtext } : {}),
        primaryCta: ctaAction(ctaBand.primary),
        ...(ctaBand.secondary ? { secondaryCta: ctaAction(ctaBand.secondary) } : {}),
      },
    });
  }

  // A real tab widget. Until now the import flattened one into a single band of
  // run-on prose: every panel's text survived and the thing that made it
  // readable — which label opens which panel — did not.
  //
  // No `media` is taken, deliberately. A tab may carry one, but claiming it
  // here would spend a photo the gallery pool has already been offered, and the
  // band reads perfectly without it.
  const scrollTabs = detectScrollTabs(html);
  if (scrollTabs) {
    built.push({
      type: "scroll-tabs",
      at: scrollTabs.at,
      // The variant has to follow what the source actually DID, exactly as it
      // does for `hero` and `about` above. The type's default is `pinned` — a
      // scroll-driven panel whose whole effect is the picture swapping beside
      // it — and this detector takes no picture and fired on a widget the
      // visitor CLICKS. `tabs` is that: click a label, swap the panel.
      variant: "tabs",
      content: {
        type: "scroll-tabs",
        ...(scrollTabs.heading ? { heading: scrollTabs.heading } : {}),
        ...(scrollTabs.intro ? { intro: scrollTabs.intro } : {}),
        tabs: scrollTabs.tabs.map((t) => ({
          label: t.label,
          ...(t.title ? { title: t.title } : {}),
          description: t.description,
        })),
      },
    });
  }

  // An inline line drawing. Until now this was not a weaker import, it was no
  // import at all: every prose reader in this pipeline strips `<svg>` before it
  // looks at the page, so the drawing left no trace anywhere.
  //
  // No heading is claimed. The band above a drawing is usually somebody else's
  // — taking it would put the same words on two sections, which is the exact
  // failure `structureSections.test.ts` already guards for `highlights`.
  const illustration = detectIllustration(html);
  if (illustration) {
    built.push({
      type: "illustration",
      at: illustration.at,
      content: {
        type: "illustration",
        viewBox: illustration.viewBox,
        paths: illustration.paths,
      },
    });
  }

  // The counters band. Values are the source's own strings, never derived.
  const socialProof = detectSocialProof(html);
  if (socialProof) {
    built.push({
      type: "social-proof",
      at: socialProof.at,
      content: {
        type: "social-proof",
        heading: socialProof.heading ?? t.socialProof,
        stats: socialProof.stats,
      },
    });
  }

  // The work grid - projects and cases, which are NAMED, so `bento` rather
  // than `gallery`: dropping the titles is exactly the fidelity loss this
  // item exists to close. Its pictures leave the gallery pool for the same
  // reason the hero's and About's do.
  const bentoUsed = new Set<string>();
  if (bento) {
    const cells = bento.cells
      .map((cell) => {
        const id = cell.imageUrl ? registry.register(cell.imageUrl, cell.title) : null;
        if (id) bentoUsed.add(id);
        return {
          title: cell.title,
          ...(cell.description ? { description: cell.description } : {}),
          ...(id ? { media: { assetId: id, alt: cell.title } } : {}),
        };
      })
      .slice(0, 9);
    built.push({
      type: "bento",
      at: bento.at,
      content: { type: "bento", heading: bento.heading, cells },
    });
  }

  // "Före / Efter" — two photographs of the same thing, and the transformation
  // between them. Gated on structure AND labels together in `detectBeforeAfter`;
  // here the only job left is registering both pictures, and DROPPING a pair
  // whose second half failed to register. Half a pair is not a weaker section,
  // it is a wrong one: the band renders a comparison, so one missing side would
  // show the same photo as its own "before".
  const beforeAfterUsed = new Set<string>();
  if (beforeAfter) {
    const pairs = beforeAfter.pairs
      .map((p) => {
        const label = p.label ?? beforeAfter.heading ?? name;
        const before = registry.register(p.beforeUrl, `${label} — före`);
        const after = registry.register(p.afterUrl, `${label} — efter`);
        if (!before || !after) return null;
        return {
          before: { assetId: before, alt: `${label} — före` },
          after: { assetId: after, alt: `${label} — efter` },
          ...(p.label ? { label: p.label } : {}),
        };
      })
      .filter((p): p is NonNullable<typeof p> => p !== null);
    if (pairs.length > 0) {
      for (const p of pairs) {
        beforeAfterUsed.add(p.before.assetId);
        beforeAfterUsed.add(p.after.assetId);
      }
      built.push({
        type: "before-after",
        at: beforeAfter.at,
        content: {
          type: "before-after",
          ...(beforeAfter.heading ? { heading: beforeAfter.heading } : {}),
          pairs,
        },
      });
    }
  }

  // The source's Instagram feed, as the thumbnails its widget had cached when
  // we fetched. A handle alone stays a social link - an empty grid under
  // "Följ oss" is worse than the link the import already carries.
  const instagramUsed = new Set<string>();
  if (instagram) {
    const images = instagram.imageUrls
      .map((url) => registry.register(url, instagram.handle ? `@${instagram.handle}` : name))
      .filter((id): id is string => id !== null);
    if (images.length >= 3) {
      for (const id of images) instagramUsed.add(id);
      built.push({
        type: "instagram",
        at: instagram.at,
        content: {
          type: "instagram",
          heading: t.instagram,
          ...(instagram.handle ? { handle: instagram.handle } : {}),
          // The source's own alt when it had one, else the handle. NOT "",
          // which is the model's marker for a deliberately decorative image
          // and would tell the publish gate to stop asking about a photo the
          // owner may well want described.
          images: images.map((assetId) => ({
            assetId,
            alt: altOf(assetId) || (instagram.handle ? `@${instagram.handle}` : name),
          })),
        },
      });
    }
  }

  const bodyByHeading = new Map(headingBlocks(html).map((b) => [b.heading, b.body]));
  const claimedHeadings = new Set(
    [
      services?.heading,
      team?.heading,
      process?.heading,
      areas?.heading,
      newsletter?.heading,
      // The bands added for item 10. Each one that was BUILT FROM a heading
      // claims it; `booking` and `comparison` take whatever heading sat above
      // them, `bento` and `documents` their own.
      documents?.heading,
      booking?.heading,
      comparison?.heading,
      socialProof?.heading,
      ctaBand?.headline,
      bento?.heading,
      beforeAfter?.heading,
    ].filter((h): h is string => !!h),
  );
  const h2 = headings(html, "h2")
    .filter((h) => !/\?\s*$/.test(h))
    // A heading already rendered as its own section must not come back as a card.
    .filter((h) => !claimedHeadings.has(h.slice(0, 80)))
    .slice(0, 6);
  if (h2.length >= 2) {
    built.push({
      type: "highlights",
      at: atOfHeading(h2[0]),
      content: {
        type: "highlights",
        heading: t.what,
        items: h2.map((h) => {
          const firstPara = stripTags(
            (bodyByHeading.get(h)?.match(/<p[^>]*>([\s\S]*?)<\/p>/i) ?? [, ""])[1] ?? "",
          );
          return {
            title: h.slice(0, 56),
            // Empty stays empty rather than inventing a description: the
            // renderer handles a title-only card, and a guessed sentence on
            // someone's website is worse than a missing one.
            description: firstPara.length >= 20 ? firstPara.slice(0, 240) : "",
          };
        }),
      },
    });
  }

  // Pricing - >=2 headings carrying a price token become a real pricing table
  // (instead of being flattened into prose).
  // `locale` here is the IMPORTED document's detected language (detectLocale
  // returns sv|en), not the sv/en/pl site language. English documents price in
  // "$"; everything else falls back to the product's own default, "kr".
  const currency = locale === "en" ? "$" : "kr";
  const pricing = detectPricing(html);
  if (pricing) {
    built.push({
      type: "pricing",
      at: atOfHeading(pricing.tiers[0]?.name),
      content: { type: "pricing", heading: t.pricing, currency, tiers: pricing.tiers },
    });
  }

  // Testimonials - <blockquote> quotes become a real testimonials section.
  //
  // ONE quote with nobody's name on it is not a testimonial, it is the page's
  // pull-quote. Importing it under a "Vad andra säger" heading attributed the
  // business's own line to an anonymous customer, which reads as a fake review
  // - and the section rendered an empty author slot underneath it. A `statement`
  // is exactly this element and carries no attribution at all.
  const quotes = detectTestimonials(html);
  const atOfQuote = html.match(/<blockquote\b/i)?.index;
  if (quotes.length === 1 && !quotes[0].author) {
    built.push({
      type: "statement",
      at: atOfQuote,
      content: { type: "statement", text: quotes[0].text },
    });
  } else if (quotes.length >= 1) {
    built.push({
      type: "testimonials",
      at: atOfQuote,
      content: { type: "testimonials", heading: t.testimonials, quotes },
    });
  }

  // FAQ - <details> accordions or "?"-headings become a real FAQ section.
  const faq = detectFaq(html);
  if (faq.length >= 2) {
    built.push({
      type: "faq",
      at: atOfHeading(faq[0]?.question),
      content: { type: "faq", heading: t.faq, items: faq },
    });
  }

  // Gallery - everything the hero, About, the work grid and the Instagram band
  // did not take, in page order. A picture rendered twice on one page is the
  // import looking broken, and the two new bands both carry pictures that were
  // in this pool a moment ago.
  const gallery = galleryPool
    .filter((id) => id !== aboutImage && !bentoUsed.has(id) && !instagramUsed.has(id))
    .slice(0, 8);
  const galleryShown = gallery.length >= 3;
  if (galleryShown) {
    built.push({
      type: "gallery",
      at: offsetOf(gallery[0]),
      content: { type: "gallery", images: gallery.map((id) => ({ assetId: id, alt: altOf(id) })) },
    });
  }

  // A captioned <figure> that no other band took. The caption is the gate, not
  // the picture: every loose image already has a home (hero, About, gallery,
  // logos) and the ones that fall through are decoration, so promoting one of
  // those would put a spacer graphic in the middle of the owner's page. A
  // `<figcaption>` is the source saying this one carries meaning - and the
  // caption itself is what `gallery` would have thrown away.
  //
  // "Taken" means RENDERED, not merely considered. `gallery` is computed
  // whether or not the band clears its three-picture floor, so counting its
  // contents unconditionally suppressed the captioned figure on exactly the
  // pages where it was the page's only loose picture - the case this is for.
  const takenImages = new Set([
    ...(imageIds[0] ? [imageIds[0]] : []),
    ...(aboutImage ? [aboutImage] : []),
    ...(galleryShown ? gallery : []),
    ...bentoUsed,
    ...instagramUsed,
    ...beforeAfterUsed,
  ]);
  for (const figure of captioned.slice(0, 3)) {
    const id = registry.register(figure.url, figure.alt || figure.caption || name);
    if (!id || takenImages.has(id)) continue;
    takenImages.add(id);
    built.push({
      type: "image",
      at: figure.at,
      content: {
        type: "image",
        image: { assetId: id, alt: figure.alt || figure.caption || name },
        ...(figure.caption ? { caption: figure.caption } : {}),
      },
    });
  }

  // Trust marks and partner logos. These used to be either dropped on sight (a
  // filename match) or - worse - mistaken for photography and rendered as the
  // page's hero. They are neither: they are a strip, and the section model has
  // had `certifications` and `logos` types for exactly this all along.
  //
  // A label is required by both types. The source's alt is the right one; a
  // filename cleaned up is the honest fallback. An image we can name NEITHER
  // way is skipped rather than labelled with the business's own name, which
  // would read as "Nordvik Bygg" under a stranger's badge.
  const strip = (
    role: "certificate" | "logo",
    type: "certifications" | "logos",
    heading: string,
    min: number,
  ) => {
    const named = candidates
      // Body only. The business's OWN mark lives in the header and is claimed
      // by `siteLogoFrom` as the site logo; repeating it under "vi samarbetar
      // med" would have the owner listing themselves as their own partner.
      .filter((c) => c.guess === role && (c.region === "body" || c.region === "aside"))
      .map((c) => ({ label: (c.alt || labelFromFilename(c.url)).slice(0, 80), url: c.url }))
      .filter((i) => i.label.length > 0)
      .slice(0, 12);
    // Count BEFORE registering. Registering first uploaded every badge and
    // partner mark on the page even when the strip was then never emitted -
    // billing the owner's asset quota, and the import's global cap, for images
    // nothing would render.
    //
    // One badge is a decoration; a row of them is a claim the owner is making.
    // `logos` needs more than `certifications` because a single "logo" on a page
    // is usually the business's own, which belongs in the header instead.
    if (named.length < min) return;
    const items = named
      .map((i) => {
        const id = registry.register(i.url, i.label);
        return id ? { label: i.label, logo: { assetId: id, alt: i.label } } : null;
      })
      .filter((i): i is NonNullable<typeof i> => i !== null);
    // The asset cap can still bite mid-strip; a one-item "row" is not a row.
    if (items.length >= min) {
      built.push({
        type,
        at: candidates.find((c) => c.url === named[0].url)?.docOffset,
        content: { type, heading, items },
      });
    }
  };
  strip("certificate", "certifications", t.certifications, 2);
  strip("logo", "logos", t.partners, 3);

  // Location - the map + address block, but only when the page showed it WANTED
  // one: a maps embed, or a "Hitta hit" / "Besöksadress" heading. The address
  // itself is only ever what the page declared (schema.org, OpenGraph, or its
  // own contact block) - never the heading, and never invented. Without the
  // intent signal the address stays where it already goes, on the contact
  // section, rather than adding a map nobody asked for.
  const wantsMap =
    /<iframe[^>]+src=["'][^"']*(?:google\.[a-z.]+\/maps|maps\.google|openstreetmap\.org|kartor\.eniro)/i.test(
      html,
    ) || headings(html, "h2").some((h) => FIND_US_HEADING.test(h));
  const postal = wantsMap ? splitAddressLine(meta.address, meta.city) : null;
  if (postal) {
    built.push({
      type: "location",
      at: atOfHeading(headings(html, "h2").find((h) => FIND_US_HEADING.test(h))),
      content: { type: "location", heading: t.findUs, address: postal },
    });
  }

  // Opening hours, from the page's own schema.org `openingHoursSpecification`.
  // `extractFromHtml` has been reading these for a while (backlog 0277) and the
  // import used them only to pre-fill onboarding - so a cafe that published its
  // hours in machine-readable markup got a migrated site with no hours on it.
  // Zero guessing: a weekday the source did not declare renders as closed,
  // which is what the section already means.
  if (meta.hours && meta.hours.length > 0) {
    const declared = new Map(meta.hours.map((h) => [h.day, h]));
    built.push({
      type: "opening-hours",
      content: {
        type: "opening-hours",
        days: (["mon", "tue", "wed", "thu", "fri", "sat", "sun"] as const).map((day) => {
          const found = declared.get(day);
          return found
            ? {
                day,
                closed: false,
                open: found.open,
                close: found.close,
                ...(found.breaks?.length ? { breaks: found.breaks } : {}),
              }
            : { day, closed: true };
        }),
      },
    });
  }

  // About - the owner's prose, and ONLY the prose no other section already
  // carries.
  //
  // It used to be every paragraph on the page except the hero's, joined
  // together - which meant an imported page showed its FAQ answers, its price
  // lines and its highlight copy a second time, in a wall of text under "Om
  // oss". Two sections saying the same thing is not fidelity, it is the import
  // looking broken. Built last for that reason: by here every other detector
  // has taken what it recognised, so this can take the remainder.
  //
  // Position comes from the FIRST remaining paragraph, so About lands where the
  // owner's story actually was rather than at a fixed rung.
  //
  // Two filters, because prose gets claimed two different ways. A detector that
  // STORES a paragraph (an FAQ answer, a highlight description) is caught by
  // comparing text. A detector that renders a block WITHOUT storing its prose -
  // pricing keeps a tier name and a price token, not the sentence under it - is
  // only caught by position: a paragraph sitting under a heading some other
  // section already took is that section's, whatever it says.
  const claimed = claimedText(built);
  const headingIndex = headingsAt(html);
  const headingAbove = (at: number | undefined): string | undefined => {
    if (at === undefined) return undefined;
    let best: string | undefined;
    for (const h of headingIndex) {
      if (h.at < at) best = h.text;
      else break;
    }
    return best;
  };
  // Only sections built FROM A HEADING claim one. Deriving this from every
  // section's offset instead claimed the heading a gallery's first photo
  // happened to sit under, which swallowed the owner's own About copy.
  //
  // Split in two on purpose. `sectionHeadings` is the narrow, honest set — a
  // heading some other band actually SHOWS. `usedHeadings` adds every `h2` on
  // the page, which is a blanket for attributing paragraphs and deliberately
  // over-claims: it is right that a paragraph under an unrecognised h2 is that
  // block's rather than About's, and wrong to conclude from the same blanket
  // that the h2 is spoken for. The rich-text band below needs the narrow one,
  // because its own title is nearly always an h2 nobody else took.
  const sectionHeadings = new Set(
    [
      services?.heading,
      team?.heading,
      process?.heading,
      areas?.heading,
      ...faq.map((item) => item.question),
      ...(pricing?.tiers.map((tier) => tier.name) ?? []),
      newsletter?.heading,
      documents?.heading,
      booking?.heading,
      comparison?.heading,
      socialProof?.heading,
      ctaBand?.headline,
      bento?.heading,
      beforeAfter?.heading,
      headings(html, "h2").find((h) => FIND_US_HEADING.test(h)),
    ].filter((h): h is string => typeof h === "string" && h.length > 0),
  );
  const usedHeadings = new Set([...sectionHeadings, ...h2]);
  const aboutRemaining = aboutParas.filter((p) => {
    if (claimed.has(textKey(p))) return false;
    const above = headingAbove(atOfParagraph(p));
    return above === undefined || !usedHeadings.has(above);
  });
  // A long-form run of the owner's own prose keeps its shape — its subheadings
  // and its bullet lists — instead of being joined into one string.
  //
  // `rich-text` REPLACES About here rather than sitting beside it, and reads the
  // very same paragraphs, so the same words can never appear on two bands. That
  // is why it is decided at this one point instead of being another detector
  // upstream: a detector with its own prose pool would compete with About for
  // it, which is the duplicate-band failure this whole tail is built to avoid.
  //
  // **Only when About would have been text-only anyway.** `rich-text` carries no
  // media, so taking this path on a page where About had a photo would trade a
  // picture for a subheading and strand the photo (the gallery needs three).
  // A picture beside the story is fidelity too.
  const richBlocks = aboutImage
    ? null
    : detectRichTextBlocks(html, aboutRemaining, claimed);
  if (richBlocks) {
    // The article's own heading if the source wrote one and no other band shows
    // it — never `t.about` ("Om oss"), which is a label we invent. The field is
    // optional precisely so a piece with no title of its own renders untitled
    // rather than mis-titled.
    //
    // Nearest **h2**, not nearest heading. The nearest heading above the first
    // kept paragraph is usually one of the article's own `h3` subheadings, and
    // taking that would title the whole piece after its first sub-point.
    const firstAt = atOfParagraph(aboutRemaining[0]);
    const own =
      firstAt === undefined
        ? undefined
        : [...html.matchAll(/<h2\b[^>]*>([\s\S]*?)<\/h2>/gi)]
            .map((m) => ({ at: m.index ?? 0, text: stripTags(m[1]) }))
            .filter((h) => h.at < firstAt && h.text.length > 1 && h.text.length < 120)
            .pop()?.text;
    const heading =
      own && !sectionHeadings.has(own) && !claimed.has(textKey(own)) ? own : undefined;
    built.push({
      type: "rich-text",
      at: atOfParagraph(aboutRemaining[0]),
      variant: "prose",
      content: {
        type: "rich-text",
        ...(heading ? { heading } : {}),
        blocks: richBlocks.slice(0, 60),
      },
    });
  } else if (aboutRemaining.length > 0) {
    built.push({
      type: "about",
      at: atOfParagraph(aboutRemaining[0]),
      variant: aboutImage ? "text-image" : "text-only",
      content: {
        type: "about",
        heading: t.about,
        body: aboutRemaining.join("\n\n").slice(0, 2000),
        ...(aboutImage ? { media: { assetId: aboutImage, alt: altOf(aboutImage) } } : {}),
      },
    });
  } else if (!built.some((b) => CONTENT_BANDS.has(b.type))) {
    // Nothing has spoken for this page yet. A page whose only content is a
    // LIST — a catering menu, a "det har ingar" page, a services rundown
    // written as bullets — reached this point with every band declining it,
    // and imported as a hero, a contact form and a footer with its own content
    // gone. `highlights` is the band that renders short labelled points, and
    // the list items are exactly that.
    const loose = detectLooseList(html, claimed);
    if (loose) {
      built.push({
        type: "highlights",
        at: html.search(/<(?:ul|ol)\b/i) >= 0 ? html.search(/<(?:ul|ol)\b/i) : undefined,
        content: {
          type: "highlights",
          heading: headings(html, "h2")[0] ?? t.what,
          items: loose.items.map((title) => ({ title, description: "" })),
        },
      });
    }
  }

  // Contact - always, so the draft has a way to get in touch.
  //
  // The FIELDS are the source's own where we can read them honestly. They used
  // to be these three unconditionally, so a form that collected "Telefon",
  // "Adress" or "Typ av uppdrag" quietly stopped collecting them the moment it
  // was imported — and nothing said so. `detectFormFields` returns null on
  // anything it cannot read cleanly, and null means these defaults, which are
  // a working form: a miss costs nothing, a wrong read costs the owner a form
  // that asks the wrong questions.
  const sourceFields = detectFormFields(html);
  built.push({
    type: "contact",
    content: {
      type: "contact",
      heading: t.contact,
      fields: sourceFields ?? [
        { key: "name", label: t.name, type: "text", required: true },
        { key: "email", label: t.email, type: "email", required: true },
        { key: "message", label: t.message, type: "textarea", required: true },
      ],
      submitLabel: t.send,
      successMessage: t.success,
    },
  });

  // Footer.
  built.push({ type: "footer", content: { type: "footer", businessName: name } });
  // The source decided the order; we only decided what each block IS.
  return inSourceOrder(built);
}

/** Slug for an imported page derived from its URL path. The site root becomes
 *  the home page (slug ""); everything else keeps a language-agnostic slug from
 *  its last path segment. Deduped by the caller. */
function slugFromUrl(url: string, homeOrigin: string): string {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return "";
  }
  // A directory-index filename is the folder it sits in, not a page of its own.
  // Without this a static export (Webflow, a plain HTML site, any zip) imported
  // its home page as "/index" and the site had no home page at all.
  const path = parsed.pathname
    .replace(/\/(?:index|default)\.(?:html?|php|aspx?)$/i, "/")
    .replace(/\/+$/, "");
  if (!path || `${parsed.origin}${path || "/"}` === `${homeOrigin}/`) return "";
  const segment = path.split("/").filter(Boolean).pop() ?? "";
  return segment
    .toLowerCase()
    .replace(/\.(html?|php|aspx?)$/i, "")
    .replace(/[^a-z0-9åäö-]+/gi, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60);
}

/**
 * The slugs the source site's own MENU links to, in menu order.
 *
 * Without this an import ordered its pages by crawl priority and put EVERY
 * discovered page in the navigation - so a 30-page crawl produced a 30-item
 * menu in an order the owner never chose, on the one part of the site a visitor
 * reads first. The owner's menu is a decision they already made; the crawl is
 * not.
 *
 * Deliberately narrow: the `<nav>`/`<header>` block with the most same-origin
 * links wins, anchors and off-site links are ignored, and a menu we cannot find
 * returns an empty array (which keeps today's behaviour rather than inventing
 * an order).
 */
export function navSlugsFromHome(html: string, homeUrl: string): string[] {
  let homeOrigin: string;
  try {
    homeOrigin = new URL(homeUrl).origin;
  } catch {
    return [];
  }
  const blocks = [
    ...[...html.matchAll(/<nav\b[^>]*>([\s\S]*?)<\/nav>/gi)].map((m) => m[1]),
    ...[...html.matchAll(/<header\b[^>]*>([\s\S]*?)<\/header>/gi)].map((m) => m[1]),
  ];
  let best: string[] = [];
  for (const block of blocks) {
    const slugs: string[] = [];
    for (const m of block.matchAll(/<a\b[^>]*\bhref=["']([^"']+)["']/gi)) {
      const href = m[1].trim();
      if (/^(?:#|mailto:|tel:|javascript:)/i.test(href)) continue;
      let abs: URL;
      try {
        abs = new URL(href, homeUrl);
      } catch {
        continue;
      }
      if (abs.origin !== homeOrigin) continue;
      const slug = slugFromUrl(abs.toString(), homeOrigin);
      // The home link is implicit - it is always first and always in the menu.
      if (slug === "" || slugs.includes(slug)) continue;
      slugs.push(slug);
    }
    if (slugs.length > best.length) best = slugs;
  }
  // One link is a logo, not a menu.
  return best.length >= 2 ? best.slice(0, 30) : [];
}

/** Turn one page of section descriptors into portable sections stamped with a
 *  page id, order keys and stable externalKeys (so a re-import merges by key). */
/**
 * The variant a MEASURED column count implies, when it disagrees with the one
 * the importer guessed.
 *
 * The guess reads item COUNT — four services must be a three-column grid — and
 * that is wrong exactly where the source made a deliberate choice: four
 * services laid out in two columns is a composition, and no count can see it.
 * A render can, so where a render happened the measurement wins.
 *
 * Deliberately narrow. It only ever moves between `grid-2` and `grid-3`, the
 * two variants that mean nothing except "how many columns", and only on the two
 * types that carry both. Everything else — `split`, `list`, `alternating`,
 * `icon-grid` — encodes something a column count does not know about (a media
 * side, a rhythm, an icon treatment), so a measurement must not overrule it.
 */
function columnVariant(
  type: BuiltSection["type"],
  guessed: string | undefined,
  columns: number,
): string | undefined {
  if (guessed !== "grid-2" && guessed !== "grid-3") return undefined;
  if (type !== "services" && type !== "highlights") return undefined;
  const measured = columns <= 2 ? "grid-2" : "grid-3";
  return measured === guessed ? undefined : measured;
}

function toPortableSections(
  built: BuiltSection[],
  pageTmpId: string,
  slug: string,
  measured?: { html: string; bands: MeasuredSectionSample[] },
): PortableSiteV1["sections"] {
  const keys = initialKeys(built.length);
  const slugKey = slug || "home";
  const bands = new Map<string, MeasuredSectionSample>();
  for (const band of measured?.bands ?? []) {
    // First occurrence wins: a page with two "Kontakt" headings has one band we
    // can attribute with confidence, and guessing at the second is how a
    // measurement lands on the wrong section.
    if (!bands.has(band.key)) bands.set(band.key, band);
  }
  const sourceHeadings =
    bands.size > 0 && measured ? headingsAt(measured.html) : [];
  return built.map((s, i) => {
    const key = bandKeyOf(s, sourceHeadings);
    const band = key ? bands.get(key) : undefined;
    const geometry = band ? bandGeometry(band) : undefined;
    const guessed = s.variant ?? variantFor(s.type);
    // The first measurement that changes WHICH variant a section gets rather
    // than how it is spaced. Only where a render actually reported columns for
    // this band; a page nobody measured keeps the guess it always had.
    const measuredVariant =
      band?.columns !== undefined ? columnVariant(s.type, guessed, band.columns) : undefined;
    return {
      pageTmpId,
      type: s.type,
      variant: measuredVariant ?? guessed,
      order: keys[i],
      content: s.content,
      ...(geometry ? { layout: { measured: geometry } } : {}),
      // `ladder`, not `i`: the key identifies WHICH detector produced this
      // section, and must not move when the source's own order does.
      externalKey: `import:sec:${slugKey}:${s.ladder ?? i}`,
    };
  });
}

/**
 * The SOURCE band a built section came out of, as the same normalised heading
 * key `readComputedDesignInPage` reported that band under.
 *
 * Matching on the built section's own heading is the obvious idea and it is
 * wrong: the importer writes its own headings ("Det vi gör" over a highlights
 * grid, "Kontakta oss" over the form it adds) and folds the source's h2 into an
 * item title. So the join runs on the SOURCE side instead — the heading nearest
 * above the byte offset the section's evidence was found at, which is exactly
 * the heading the browser read off that band. The section's own heading is only
 * a fallback, for a detector that carried the source wording through (About).
 */
function bandKeyOf(
  section: BuiltSection,
  headings: Array<{ text: string; at: number }>,
): string | undefined {
  if (section.at !== undefined) {
    let best: string | undefined;
    for (const heading of headings) {
      if (heading.at > section.at) break;
      best = heading.text;
    }
    const key = measuredKey(best);
    if (key) return key;
  }
  const content = section.content;
  if (!content || typeof content !== "object") return undefined;
  const record = content as Record<string, unknown>;
  for (const field of ["heading", "headline", "title", "name"]) {
    const value = record[field];
    if (typeof value === "string" && value.trim()) return measuredKey(value);
  }
  return undefined;
}

/** Drop the key and keep the geometry — `section.layout.measured` is the band's
 *  numbers, not how we found them. `undefined` when the band measured nothing. */
function bandGeometry(
  band: MeasuredSectionSample,
): NonNullable<SectionLayout["measured"]> | undefined {
  const geometry: NonNullable<SectionLayout["measured"]> = {};
  if (band.paddingTop) geometry.paddingTop = band.paddingTop;
  if (band.paddingBottom) geometry.paddingBottom = band.paddingBottom;
  if (band.maxWidth) geometry.maxWidth = band.maxWidth;
  if (band.gap) geometry.gap = band.gap;
  if (band.align) geometry.align = band.align;
  return Object.keys(geometry).length > 0 ? geometry : undefined;
}

/**
 * Build a rough, schema-valid single-page portable site from a page of HTML.
 * @param css Optional linked stylesheets the caller fetched. Inline <style>
 *            blocks are read from `html` automatically; pass external CSS here
 *            (in load order) to improve brand-colour detection.
 */
export function htmlToPortableSite(
  html: string,
  baseUrl: string,
  css: string | string[] = [],
  sample?: ComputedSample,
): PortableSiteV1 {
  return htmlToPortableSiteWithDesign(html, baseUrl, css, sample).site;
}

/** Same conversion, but also hands back the design signals it read, so a caller
 *  can build the human-facing import summary without parsing the page twice. */
export function htmlToPortableSiteWithDesign(
  html: string,
  baseUrl: string,
  css: string | string[] = [],
  sample?: ComputedSample,
): {
  site: PortableSiteV1;
  design: ExtractedDesign;
  fonts: ImportFonts;
  /** Images skipped because the per-import asset cap was hit (0 when under). */
  droppedAssets: number;
  /** What the source page declared (Adobe kit, motion libraries, embeds,
   *  placeholder copy) - drives the owner's post-import to-do list. */
  signals: SourceSignals;
} {
  const meta = extractFromHtml(html, baseUrl);
  const locale = detectLocale(html);
  const t = COPY[locale];
  const rawSignals = detectSourceSignals(html, css);
  const staticDesign = extractDesign(html, css);
  const design = sample ? applyComputedSample(staticDesign, sample) : staticDesign;
  const fonts = importFonts(design);
  const registry = new AssetRegistry();
  const built = buildPageSections(html, baseUrl, locale, registry, heroVariantFor(design.heroLayout));
  // A video we DID bring across is not an embed that "didn't come over". The
  // receipt counted every <iframe> on the page, so importing the owner's
  // presentation video still told them one embed was lost.
  const signals = withCarriedEmbeds(rawSignals, built);
  const name = (meta.businessName?.trim() || headings(html, "h1")[0] || t.heroFallback).slice(0, 120);

  const site: PortableSiteV1 = {
    format: "sajt-site",
    version: 1,
    exportedAt: "",
    site: {
      businessName: name,
      vertical: "generic",
      goal: "show_services",
      language: locale,
      theme: themeFromDesign(design, fonts, signals.motionLibs.length > 0),
      contact: { phone: meta.phone, email: meta.email },
      socials: meta.socials,
      tracking: meta.tracking,
      ...(() => {
        const logo = siteLogoFrom(html, baseUrl, registry, name);
        return logo ? { logoAssetId: logo } : {};
      })(),
    },
    fontsAssignment: fonts.fontsAssignment,
    folders: [],
    pages: [
      {
        tmpId: "home",
        slug: "",
        title: name.slice(0, 60) || t.home,
        order: 10,
        showInNav: true,
        seo: pageSeoFrom(html, baseUrl),
      },
    ],
    sections: toPortableSections(
      built,
      "home",
      "",
      sample?.sections ? { html, bands: sample.sections } : undefined,
    ),
    fonts: fonts.fonts,
    assets: registry.assets,
  };
  return { site, design, fonts, droppedAssets: registry.droppedCount, signals };
}

export type ImportPageInput = {
  url: string;
  html: string;
  title?: string;
  language?: string;
  /** Linked stylesheets the fetcher already had, in load order. Only the HOME
   *  page's CSS affects the site design (brand colour / fonts / radius), but
   *  carrying it per page keeps the input shape uniform. */
  css?: string[];
  /** The page's own linked SCRIPT files, for motion extraction (a Webflow
   *  export keeps its interaction payload in `js/webflow.js`). Parsed, never
   *  executed - see lib/import/objectLiteral. Home page only, same as `css`. */
  scripts?: string[];
  /** Set when this input is a BLOG POST rather than an ordinary page, and the
   *  source told us so rather than us guessing from its URL.
   *
   *  Set from EVIDENCE, never from a resemblance. Three sources qualify: the
   *  WordPress REST API (`lib/import/wpRest.ts`) and an RSS/Atom feed
   *  (`lib/import/rssBlog.ts`), which both say outright that an item is a post
   *  and carry its author, date and excerpt as fields; and a crawled page that
   *  clears `extractArticleMetadata`'s bar — a post-shaped URL AND either a
   *  JSON-LD `Article` or an `<article>` element with a real publication date.
   *
   *  The bar is high on purpose and in one direction: a page wrongly typed as a
   *  post vanishes from the menu into a news list, which is a defect the owner
   *  has to find and cannot easily undo, while a post left as a page is an
   *  ordinary page they can still see. */
  post?: {
    excerpt?: string;
    author?: string;
    firstPublishedAt?: number;
    /** Categories as the source named them. Kept for the report today; the
     *  editor has no per-post taxonomy to write them into yet. */
    categories?: string[];
  };
};

export type MultiPageReport = {
  homeUrl: string;
  pages: Array<{ url: string; slug: string; title: string; sections: number }>;
  /** Images skipped because the import asset cap was hit (0 when under cap).
   *  Surfaced so the import summary never hides truncation. */
  droppedAssets: number;
};

/** Build ONE portable site from every crawled page of a real site. Each input
 *  becomes its own page (home = slug ""), images dedupe across pages, and
 *  site-level facts (name/contact/socials/tracking) come from the home page
 *  with gaps filled from the rest. Nav is derived; nothing is invented. The
 *  result is a rough multi-page DRAFT the owner reviews, never a clone. */
export function multiPageToPortableSite(
  input: ImportPageInput[],
  homeUrl: string,
  /** Design signals read from the RENDERED home page (a headless render step,
   *  see lib/import/sampleComputedStyles.ts). When present it overrides what
   *  static parsing guessed, so a Tailwind/CSS-var site gets its real brand
   *  colour instead of the framework default. Absent = static-only (unchanged). */
  opts?: {
    sample?: ComputedSample;
    /** Renders of pages OTHER than the home page, keyed by absolute source URL
     *  (backlog 1725 item 4).
     *
     *  Per-band geometry measured on the home page is a measurement there and
     *  a guess anywhere else, so until this existed every subpage of a crawl
     *  fell back to the renderer's own spacing while the home page wore the
     *  source's - the one difference an owner notices immediately when they
     *  click through from a landing page to an article.
     *
     *  The caller decides WHICH pages are worth a render
     *  (`pickTemplatePages`); this only applies what it was given. A page not
     *  in the map is unmeasured and gets no per-band geometry, which is the
     *  previous behaviour and still the honest one. The site THEME stays the
     *  home page's alone: a site has one theme, and letting an article's
     *  render repaint the whole site would be a regression dressed as a
     *  feature. */
    samplesByUrl?: ReadonlyMap<string, ComputedSample>;
    /** Every source URL discovery FOUND, including the ones this import did not
     *  fetch - a truncated crawl, a page the cap dropped, a URL that failed.
     *
     *  Without them those addresses simply 404 after the domain is cut over,
     *  which is the top complaint in every site-migration post-mortem and the
     *  thing owners are actually afraid of. They are matched to an imported
     *  page by first path segment; anything with no plausible target is left
     *  alone rather than dumped on the home page, because a blanket redirect to
     *  "/" is a soft 404 and search engines treat it as one. */
    discoveredUrls?: string[];
    /** What a vision model made of the pictures, keyed by absolute image URL.
     *  Optional and best-effort: see `convex/import/imageRoles.ts`. */
    imageVerdicts?: ImageVerdicts;
  },
): {
  site: PortableSiteV1;
  report: MultiPageReport;
  /** The home page's design signals, so the caller can build the human-facing
   *  import summary (lib/import/importSummary.ts) without re-parsing. */
  design?: ExtractedDesign;
  fonts?: ImportFonts;
  /** Adobe kit + motion libraries from the home page, embeds + placeholder
   *  copy summed across every crawled page. Drives the post-import to-do list. */
  signals: SourceSignals;
} {
  const homeOrigin = (() => {
    try {
      return new URL(homeUrl).origin;
    } catch {
      return "";
    }
  })();

  // The source site's OWN menu decides both the order of the imported pages and
  // which of them are in the navigation. Before this the order was crawl
  // priority and every discovered page went into the menu, so a 30-page crawl
  // produced a 30-item nav in an order the owner never chose - on the one part
  // of the site a visitor reads first. A site whose menu we cannot find keeps
  // exactly the previous behaviour.
  const homeInput = input.find((p) => slugFromUrl(p.url, homeOrigin) === "") ?? input[0];
  const navSlugs = homeInput ? navSlugsFromHome(homeInput.html, homeInput.url) : [];
  const navRank = new Map(navSlugs.map((slug, i) => [slug, i]));

  // Home first, then the menu's order, then everything else in discovery order
  // (`sort` is stable, so unranked pages keep the order the crawl found them).
  const ordered = [...input].sort((a, b) => {
    const sa = slugFromUrl(a.url, homeOrigin) === "" ? -1 : 0;
    const sb = slugFromUrl(b.url, homeOrigin) === "" ? -1 : 0;
    if (sa !== sb) return sa - sb;
    const ra = navRank.get(slugFromUrl(a.url, homeOrigin)) ?? Number.MAX_SAFE_INTEGER;
    const rb = navRank.get(slugFromUrl(b.url, homeOrigin)) ?? Number.MAX_SAFE_INTEGER;
    return ra - rb;
  });

  // Design (brand colour / fonts / radius / hero layout) is read once from the
  // home page and applied site-wide, so every imported page shares one coherent
  // look that matches the original.
  const homeStatic = homeInput
    ? extractDesign(homeInput.html, homeInput.css ?? [], homeInput.scripts ?? [])
    : undefined;
  const homeDesign =
    homeStatic && opts?.sample ? applyComputedSample(homeStatic, opts.sample) : homeStatic;
  const homeFonts = homeDesign ? importFonts(homeDesign) : undefined;
  const heroVariant = homeDesign ? heroVariantFor(homeDesign.heroLayout) : undefined;
  // Source signals come from the HOME page, like the design does: it is the
  // page whose fonts and motion set the whole site's look. Embeds and
  // placeholder copy are summed across EVERY page though - "3 embeds didn't
  // come over" has to count the contact page's map too.
  const rawSignals: SourceSignals = ordered.reduce<SourceSignals>(
    (acc, page, i) => {
      const pageSignals = detectSourceSignals(page.html, page.css ?? [], page.url);
      const isHome = page === homeInput;
      return {
        adobeKitIds: isHome || i === 0 ? pageSignals.adobeKitIds : acc.adobeKitIds,
        motionLibs: isHome || i === 0 ? pageSignals.motionLibs : acc.motionLibs,
        embeds: acc.embeds + pageSignals.embeds,
        placeholders: acc.placeholders + pageSignals.placeholders,
        // Readability is judged on the HOME page, like the design is. A crawl
        // legitimately picks up a short page or two; "the site came back empty"
        // is a statement about the page whose text we built the site from.
        content: isHome || i === 0 ? pageSignals.content : acc.content,
        // A store is a whole-SITE fact, so it unions across pages like the
        // counts do: the shop fingerprint usually sits on the home page while
        // the cart link only appears on a product page, and neither page on its
        // own clears the two-of-three bar.
        commerce: mergeCommerceDetections(acc.commerce, pageSignals.commerce),
      };
    },
    { adobeKitIds: [], motionLibs: [], embeds: 0, placeholders: 0, commerce: null },
  );

  const registry = new AssetRegistry();
  const usedSlugs = new Set<string>();
  const pages: PortableSiteV1["pages"] = [];
  const sections: PortableSiteV1["sections"] = [];
  const reportPages: MultiPageReport["pages"] = [];

  // Site-level meta accumulates: home wins, others fill scalar gaps.
  let siteName = "";
  let siteLogoAssetId: string | undefined;
  let siteLocale: "sv" | "en" = "sv";
  const contact: { phone?: string; email?: string } = {};
  let socials: PortableSiteV1["site"]["socials"];
  let tracking: PortableSiteV1["site"]["tracking"];
  /** Whether any input declared itself a post. Decides whether the site gets a
   *  blog collection at all - see the `contentCollections` note below. */
  let hasPosts = false;
  /** Slugs that became POSTS. A post is not served at `/<slug>` but at
   *  `/news/<slug>` (`lib/site/news.ts`), so its redirect target and the set of
   *  paths the redirect validator considers live both differ from a page's. */
  const postSlugs = new Set<string>();

  let order = 10;
  for (const page of ordered) {
    const rawSlug = slugFromUrl(page.url, homeOrigin);
    // Only ONE home page: a second root-ish URL is demoted to a normal slug.
    let slug = rawSlug;
    if (slug === "" && usedSlugs.has("")) continue;
    // Dedupe slug collisions deterministically.
    if (slug !== "") {
      let candidate = slug;
      let n = 2;
      while (usedSlugs.has(candidate)) candidate = `${slug}-${n++}`;
      slug = candidate;
    }
    usedSlugs.add(slug);

    const meta = extractFromHtml(page.html, page.url);
    const locale = detectLocale(page.html);
    const built = buildPageSections(
      page.html,
      page.url,
      locale,
      registry,
      heroVariant,
      opts?.imageVerdicts,
    );
    const tmpId = slug || "home";
    const t = COPY[locale];
    // A `<title>` is "<page> <sep> <brand>" far more often than not, so using it
    // raw put "Sortiment :: Hantverksbolaget" straight into the imported site's
    // navigation (verified against a real site, 2026-07-27). Drop the brand
    // segment; `pageTitleFromDocumentTitle` keeps the title untouched whenever
    // it cannot tell the two apart.
    const brandForTitle = meta.businessName?.trim() || siteName;
    // A zip/codebase import supplies no `title` (there is no crawler to read one),
    // so this fell through to the business name and EVERY page in the import was
    // called "Nordvik Bygg". The document's own <title> is right there.
    const documentTitle =
      page.title?.trim() ||
      stripTags(page.html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? "");
    const title = (
      pageTitleFromDocumentTitle(documentTitle, brandForTitle, page.url) ||
      meta.businessName?.trim() ||
      headings(page.html, "h1")[0] ||
      (slug ? slug.replace(/-/g, " ") : t.home)
    ).slice(0, 60);

    // Page SEO. This was written NOWHERE: `pages.push` carried no `seo` key at
    // all, even though the bundle format has carried `metaTitle`/
    // `metaDescription`/`canonical`/`sourceUrl` all along. So a migration threw
    // away every page title and description the owner had - the two fields that
    // decide what Google shows - and the new site started from our generated
    // defaults. Only fields the page actually declared are written; a missing
    // meta description stays missing rather than being invented.
    const seo = pageSeoFrom(page.html, page.url, page.title);

    // A post the SOURCE declared as one (WordPress REST, an RSS/Atom feed).
    // Never inferred - see `ImportPageInput.post`.
    const post = page.post;
    if (post) {
      hasPosts = true;
      postSlugs.add(slug);
    }

    pages.push({
      tmpId,
      slug,
      title: title || t.home,
      order,
      // In the menu if the SOURCE menu had it. Home is always in it, and a site
      // whose menu we could not read keeps every page in the nav as before -
      // hiding pages on a guess would be worse than a long menu.
      //
      // A post is the exception in both directions: it belongs to the blog
      // listing, not the menu, and thirty posts in a small business's top nav
      // is not a long menu - it is a broken one.
      showInNav: post ? false : navRank.size === 0 || rawSlug === "" || navRank.has(rawSlug),
      externalKey: `import:${post ? "post" : "page"}:${slug || "home"}`,
      ...(post
        ? {
            pageType: "post" as const,
            collectionTmpId: BLOG_COLLECTION_TMP_ID,
            ...(post.excerpt ? { excerpt: post.excerpt } : {}),
            ...(post.author ? { author: post.author } : {}),
            ...(post.firstPublishedAt !== undefined
              ? { firstPublishedAt: post.firstPublishedAt }
              : {}),
          }
        : {}),
      seo,
    });
    // Per-band geometry comes from THIS page's own render, or from nowhere.
    // Attributing a home band's padding to a subpage that happens to share a
    // heading would be a guess dressed as a measurement - so a page the caller
    // did not measure keeps the renderer's defaults, exactly as before item 4.
    const pageBands =
      (slug === "" ? opts?.sample?.sections : undefined) ??
      opts?.samplesByUrl?.get(page.url)?.sections;
    sections.push(
      ...toPortableSections(
        built,
        tmpId,
        slug,
        pageBands ? { html: page.html, bands: pageBands } : undefined,
      ),
    );
    reportPages.push({ url: page.url, slug, title: title || t.home, sections: built.length });
    order += 10;

    // Home page (first, slug "") sets the site identity; others only fill gaps.
    if (slug === "") {
      siteName = (meta.businessName?.trim() || title || "").slice(0, 120);
      siteLocale = locale;
      // The logo, from the home page's header only. Every other page carries the
      // same one, and a subpage header is likelier to hold a section mark.
      siteLogoAssetId = siteLogoFrom(page.html, page.url, registry, siteName);
      if (meta.phone) contact.phone = meta.phone;
      if (meta.email) contact.email = meta.email;
      socials = meta.socials;
      tracking = meta.tracking;
    } else {
      if (!contact.phone && meta.phone) contact.phone = meta.phone;
      if (!contact.email && meta.email) contact.email = meta.email;
      if (!socials && meta.socials) socials = meta.socials;
      if (!tracking && meta.tracking) tracking = meta.tracking;
    }
  }

  if (!siteName) {
    siteName = pages[0]?.title || COPY[siteLocale].heroFallback;
  }

  // SEO: old URL → new slug redirects for every crawled page whose original
  // pathname differs from its new slug (nested paths "/tjanster/massage",
  // ".html"/".php" suffixes, renamed segments). This is what actually backs the
  // "keep your Google position" promise on /migrate - the commit applies these
  // through the same transactional rail as manual redirects. Candidates are
  // pre-validated with the SAME pure validator the commit uses and invalid ones
  // are DROPPED here: one odd old URL must never roll back the whole import
  // (the commit-side validator throws on any bad row).
  const redirectCandidates: PortableRedirect[] = [];
  const seenFrom = new Set<string>();
  /** Where a slug is actually SERVED. A post lives under the news segment, so a
   *  redirect written to its bare slug would point at a path that does not
   *  exist - the one thing a redirect map must never do. */
  const livePathFor = (slug: string) =>
    postSlugs.has(slug) ? `${NEWS_SEGMENT}/${slug}` : slug;
  for (const reportPage of reportPages) {
    const fromPath = normalizeRedirectPath(reportPage.url);
    const toPath = livePathFor(reportPage.slug);
    if (fromPath === "" || fromPath === toPath || seenFrom.has(fromPath)) {
      continue;
    }
    seenFrom.add(fromPath);
    redirectCandidates.push({ fromPath, toPath });
    if (redirectCandidates.length >= PORTABLE_CAPS.maxRedirects) break;
  }

  // Addresses discovery found but this import did not land. Matched on the first
  // path segment - "/tjanster/kok" follows "/tjanster" to wherever that page
  // went - so a redirect is only written when there is a real destination.
  for (const url of opts?.discoveredUrls ?? []) {
    if (redirectCandidates.length >= PORTABLE_CAPS.maxRedirects) break;
    const fromPath = normalizeRedirectPath(url);
    if (fromPath === "" || seenFrom.has(fromPath) || usedSlugs.has(fromPath)) continue;
    const firstSegment = fromPath.split("/")[0] ?? "";
    if (!firstSegment) continue;
    const target = reportPages.find((rp) => {
      const rpFirst = normalizeRedirectPath(rp.url).split("/")[0] ?? "";
      return rpFirst === firstSegment && rp.slug !== "";
    });
    if (!target) continue;
    seenFrom.add(fromPath);
    redirectCandidates.push({ fromPath, toPath: livePathFor(target.slug) });
  }
  let redirects: PortableRedirect[] | undefined;
  if (redirectCandidates.length > 0) {
    const validated = validateRedirectMap(redirectCandidates, {
      // Posts are live at `news/<slug>`, not at `<slug>` - the validator has to
      // be told both or it drops every post redirect as pointing nowhere.
      livePaths: new Set([
        ...[...usedSlugs].filter((slug) => !postSlugs.has(slug)),
        ...[...postSlugs].map((slug) => `${NEWS_SEGMENT}/${slug}`),
      ]),
      locales: LOCALES,
      reservedPaths: [NEWS_SEGMENT],
    });
    const bad = new Set(validated.issues.map((issue) => issue.index));
    const ok = validated.redirects.filter((_, i) => !bad.has(i));
    if (ok.length > 0) redirects = ok;
  }

  const signals = withCarriedEmbeds(rawSignals, sections);

  const site: PortableSiteV1 = {
    format: "sajt-site",
    version: 1,
    exportedAt: "",
    site: {
      businessName: siteName,
      vertical: "generic",
      goal: "show_services",
      language: siteLocale,
      theme:
        homeDesign && homeFonts
          ? themeFromDesign(homeDesign, homeFonts, signals.motionLibs.length > 0)
          : {
              palette: "slate",
              fontPair: "modern",
              density: "comfortable",
              radius: "soft",
              buttonStyle: "solid",
            },
      contact,
      socials,
      tracking,
      ...(siteLogoAssetId ? { logoAssetId: siteLogoAssetId } : {}),
    },
    fontsAssignment: homeFonts?.fontsAssignment,
    folders: [],
    // A collection only exists when posts actually arrived. An empty blog in
    // the Pages panel is a promise of content the owner does not have, and the
    // panel hides posts whose collection is missing - so this and the pages'
    // `collectionTmpId` above have to be written together or not at all.
    ...(hasPosts
      ? {
          contentCollections: [
            {
              tmpId: BLOG_COLLECTION_TMP_ID,
              kind: "blog" as const,
              name: COPY[siteLocale].blogName,
              slugPrefix: NEWS_SEGMENT,
              order: 10,
            },
          ],
        }
      : {}),
    pages,
    redirects,
    sections,
    fonts: homeFonts?.fonts ?? [],
    assets: registry.assets,
  };

  return {
    site,
    report: { homeUrl, pages: reportPages, droppedAssets: registry.droppedCount },
    design: homeDesign,
    fonts: homeFonts,
    signals,
  };
}
